import React, { useState, useEffect, useMemo } from 'react';
import { useOutletContext } from 'react-router-dom';
import { supabase } from '../lib/supabaseClient';
import { MoreVertical, CheckCircle2, Trash2, Edit, X, Calendar, Layout, Copy, ChevronLeft, ChevronRight, Search } from 'lucide-react';
import '../index.css';

const ITEMS_PER_PAGE = 10;

const TasksPage = () => {
    const { searchTerm, updateSearchCount } = useOutletContext();
    const [tasks, setTasks] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedTasks, setSelectedTasks] = useState([]);
    const [isAllSelected, setIsAllSelected] = useState(false);
    const [showCreateModal, setShowCreateModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const [selectedTask, setSelectedTask] = useState(null);
    const [actionMenuOpen, setActionMenuOpen] = useState(null);
    const [currentAdmin, setCurrentAdmin] = useState(null);
    const [usersList, setUsersList] = useState([]);
    const [copiedId, setCopiedId] = useState(null);

    // Filters
    const [idSearch, setIdSearch] = useState('');
    const [dateFilter, setDateFilter] = useState('all');
    const [sortOrder, setSortOrder] = useState('az');
    const [currentPage, setCurrentPage] = useState(1);

    useEffect(() => {
        fetchTasks();
    }, []);

    const fetchTasks = async () => {
        setIsLoading(true);

        const currentAdminId = localStorage.getItem('admin_user_id');
        const [tasksRes, usersRes] = await Promise.all([
            supabase.from('tasks').select('*, assignee:users!user_id(id, username)').order('created_at', { ascending: false }),
            supabase.from('users').select('*')
        ]);

        if (tasksRes.error) {
            console.error('Error fetching tasks:', tasksRes.error);
        } else {
            const mappedData = (tasksRes.data || []).map(t => ({
                ...t,
                assignee: t.users
            }));
            setTasks(mappedData);
        }

        if (!usersRes.error) setUsersList(usersRes.data || []);
        // The original code had `setCurrentAdmin` based on `adminRes`, but `adminRes` is no longer fetched separately.
        // If `currentAdmin` is needed, it should be derived from `usersRes` or fetched explicitly.
        // For now, keeping `setCurrentAdmin` as it was, assuming `currentAdmin` might be set elsewhere or not critical here.
        // If `currentAdmin` is meant to be the logged-in user, it should be fetched from `usersRes` based on `currentAdminId`.
        if (currentAdminId && usersRes.data) {
            const admin = usersRes.data.find(user => user.id === currentAdminId);
            if (admin) setCurrentAdmin(admin);
        }

        setIsLoading(false);
    };

    const getDateFilterStart = (filter) => {
        const now = new Date();
        switch (filter) {
            case 'today':
                return new Date(now.getFullYear(), now.getMonth(), now.getDate());
            case 'week':
                return new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
            case 'month':
                return new Date(now.getFullYear(), now.getMonth() - 1, now.getDate());
            case '6months':
                return new Date(now.getFullYear(), now.getMonth() - 6, now.getDate());
            case 'year':
                return new Date(now.getFullYear() - 1, now.getMonth(), now.getDate());
            default:
                return null;
        }
    };

    const filteredTasks = useMemo(() => {
        let result = [...tasks];

        // Global search
        if (searchTerm) {
            const lowerSearch = searchTerm.toLowerCase();
            result = result.filter(task =>
                (task.title?.toLowerCase() || '').includes(lowerSearch) ||
                (task.assignee?.username?.toLowerCase() || '').includes(lowerSearch)
            );
        }

        // ID search
        if (idSearch) {
            result = result.filter(task =>
                task.id?.toString().toLowerCase().includes(idSearch.toLowerCase())
            );
        }

        // Date filter
        const dateStart = getDateFilterStart(dateFilter);
        if (dateStart) {
            result = result.filter(task => {
                const taskDate = task.created_at ? new Date(task.created_at) : null;
                return taskDate && taskDate >= dateStart;
            });
        }

        // Sort
        if (sortOrder === 'az') {
            result.sort((a, b) => (a.title || '').localeCompare(b.title || '', 'ru'));
        } else if (sortOrder === 'date_desc') {
            result.sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0));
        } else if (sortOrder === 'date_asc') {
            result.sort((a, b) => new Date(a.created_at || 0) - new Date(b.created_at || 0));
        }

        return result;
    }, [tasks, searchTerm, idSearch, dateFilter, sortOrder]);

    useEffect(() => {
        updateSearchCount(searchTerm ? filteredTasks.length : 0);
    }, [filteredTasks.length, searchTerm, updateSearchCount]);

    useEffect(() => {
        setCurrentPage(1);
    }, [idSearch, dateFilter, sortOrder, searchTerm]);

    const totalPages = Math.ceil(filteredTasks.length / ITEMS_PER_PAGE);
    const paginatedTasks = filteredTasks.slice(
        (currentPage - 1) * ITEMS_PER_PAGE,
        currentPage * ITEMS_PER_PAGE
    );

    const handleSelectAll = () => {
        if (isAllSelected) {
            setSelectedTasks([]);
            setIsAllSelected(false);
        } else {
            setSelectedTasks(paginatedTasks.map(t => t.id));
            setIsAllSelected(true);
        }
    };

    const handleSelectTask = (id) => {
        setSelectedTasks(prev =>
            prev.includes(id) ? prev.filter(tid => tid !== id) : [...prev, id]
        );
        setIsAllSelected(false);
    };

    const handleDeleteTask = async (id) => {
        if (window.confirm('Вы уверены, что хотите удалить эту задачу?')) {
            const { error } = await supabase.from('tasks').delete().eq('id', id);
            if (error) alert('Ошибка удаления: ' + error.message);
            else fetchTasks();
        }
    };

    const handleDeleteSelected = async () => {
        if (window.confirm(`Удалить выбранные задачи (${selectedTasks.length})?`)) {
            const { error } = await supabase.from('tasks').delete().in('id', selectedTasks);
            if (error) alert('Ошибка удаления: ' + error.message);
            else {
                fetchTasks();
                setSelectedTasks([]);
                setIsAllSelected(false);
            }
        }
    };

    const handleCompleteTask = async (id) => {
        const { error } = await supabase.from('tasks').update({ status: 'done' }).eq('id', id);
        if (error) alert('Ошибка: ' + error.message);
        else fetchTasks();
    };

    const handleCreateTask = async (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const newTask = Object.fromEntries(formData.entries());

        const { error } = await supabase.from('tasks').insert([newTask]);
        if (error) alert('Ошибка создания: ' + error.message);
        else {
            setShowCreateModal(false);
            fetchTasks();
        }
    };

    const handleUpdateTask = async (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const updates = Object.fromEntries(formData.entries());

        const { error } = await supabase.from('tasks').update(updates).eq('id', selectedTask.id);
        if (error) alert('Ошибка обновления: ' + error.message);
        else {
            setShowEditModal(false);
            fetchTasks();
        }
    };

    const copyToClipboard = (id) => {
        navigator.clipboard.writeText(id);
        setCopiedId(id);
        setTimeout(() => setCopiedId(null), 1500);
    };

    const getPriorityClass = (priority) => {
        switch (priority) {
            case 'high': return 'status-error';
            case 'medium': return 'status-warning';
            case 'low': return 'status-success';
            default: return 'status-neutral';
        }
    };

    const renderPagination = () => {
        if (totalPages <= 1) return null;
        const pages = [];
        const maxVisible = 5;
        let start = Math.max(1, currentPage - Math.floor(maxVisible / 2));
        let end = Math.min(totalPages, start + maxVisible - 1);
        if (end - start < maxVisible - 1) {
            start = Math.max(1, end - maxVisible + 1);
        }

        for (let i = start; i <= end; i++) {
            pages.push(i);
        }

        return (
            <div className="pagination">
                <button disabled={currentPage === 1} onClick={() => setCurrentPage(p => p - 1)}>
                    <ChevronLeft size={16} />
                </button>
                {start > 1 && (
                    <>
                        <button onClick={() => setCurrentPage(1)}>1</button>
                        {start > 2 && <span style={{ color: 'var(--text-secondary)', padding: '0 4px' }}>...</span>}
                    </>
                )}
                {pages.map(p => (
                    <button key={p} className={p === currentPage ? 'active' : ''} onClick={() => setCurrentPage(p)}>
                        {p}
                    </button>
                ))}
                {end < totalPages && (
                    <>
                        {end < totalPages - 1 && <span style={{ color: 'var(--text-secondary)', padding: '0 4px' }}>...</span>}
                        <button onClick={() => setCurrentPage(totalPages)}>{totalPages}</button>
                    </>
                )}
                <button disabled={currentPage === totalPages} onClick={() => setCurrentPage(p => p + 1)}>
                    <ChevronRight size={16} />
                </button>
            </div>
        );
    };

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '24px' }}>
                <div style={{ display: 'flex', gap: '12px' }}>
                    <button className="btn btn-primary" onClick={() => setShowCreateModal(true)}>
                        + Создать задачу
                    </button>
                </div>
            </div>

            <div className="card-static" style={{ overflow: 'hidden' }}>
                {/* Filter Bar */}
                <div className="filter-bar">
                    <div className="filter-group" style={{ width: '280px' }}>
                        <label>Поиск по задачам</label>
                        <div style={{ position: 'relative' }}>
                            <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="text"
                                placeholder="Название задачи..."
                                className="filter-input"
                                value={searchTerm}
                                onChange={(e) => updateSearchCount(e.target.value)}
                                style={{ paddingLeft: '36px', width: '100%' }}
                            />
                        </div>
                    </div>
                    <div className="filter-group" style={{ width: '180px' }}>
                        <label>Поиск по ID</label>
                        <div style={{ position: 'relative' }}>
                            <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="text"
                                placeholder="ID..."
                                className="filter-input"
                                value={idSearch}
                                onChange={(e) => setIdSearch(e.target.value)}
                                style={{ paddingLeft: '36px', width: '100%' }}
                            />
                        </div>
                    </div>
                    <div className="filter-group">
                        <label>Дата</label>
                        <select
                            className="filter-select"
                            value={dateFilter}
                            onChange={(e) => setDateFilter(e.target.value)}
                        >
                            <option value="all">Все</option>
                            <option value="today">За Сегодня</option>
                            <option value="week">За Неделю</option>
                            <option value="month">За Месяц</option>
                            <option value="6months">За 6 Месяцев</option>
                            <option value="year">За 1 Год</option>
                        </select>
                    </div>
                    <div className="filter-group">
                        <label>Сортировка</label>
                        <select
                            className="filter-select"
                            value={sortOrder}
                            onChange={(e) => setSortOrder(e.target.value)}
                        >
                            <option value="az">А до Я</option>
                            <option value="za">Я до А</option>
                            <option value="date_desc">Дата добавления (сначала новые)</option>
                            <option value="date_asc">Дата добавления (сначала старые)</option>
                        </select>
                    </div>
                </div>

                {/* Table */}
                <div className="table-container">
                    <table>
                        <thead>
                            <tr>
                                <th style={{ width: '40px', paddingLeft: '24px' }}>
                                    <input
                                        type="checkbox"
                                        checked={isAllSelected}
                                        onChange={handleSelectAll}
                                        style={{ width: '18px', height: '18px', accentColor: 'var(--primary-color)' }}
                                    />
                                </th>
                                <th>ID</th>
                                <th>Название</th>
                                <th>Исполнитель</th>
                                <th>Приоритет</th>
                                <th>Дата</th>
                                <th style={{ width: '60px' }}></th>
                            </tr>
                        </thead>
                        <tbody>
                            {isLoading ? (
                                <tr><td colSpan="7" style={{ textAlign: 'center', padding: '48px' }}>Загрузка...</td></tr>
                            ) : paginatedTasks.length === 0 ? (
                                <tr><td colSpan="7" style={{ textAlign: 'center', padding: '48px' }}>Ничего не найдено</td></tr>
                            ) : paginatedTasks.map((task) => (
                                <tr
                                    key={task.id}
                                    className={searchTerm && (task.title?.toLowerCase().includes(searchTerm.toLowerCase())) ? 'search-highlight' : ''}
                                    style={{ background: selectedTasks.includes(task.id) ? 'var(--primary-light)' : 'transparent' }}
                                >
                                    <td style={{ paddingLeft: '24px' }}>
                                        <input
                                            type="checkbox"
                                            checked={selectedTasks.includes(task.id)}
                                            onChange={() => handleSelectTask(task.id)}
                                            style={{ width: '18px', height: '18px', accentColor: 'var(--primary-color)' }}
                                        />
                                    </td>
                                    <td>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                                            <span style={{ color: 'var(--primary-color)', fontWeight: 600, fontSize: '13px' }}>
                                                #{task.id?.toString().slice(0, 8)}
                                            </span>
                                            <button
                                                className="copy-btn"
                                                onClick={() => copyToClipboard(task.id)}
                                                title="Копировать ID"
                                                style={{ color: copiedId === task.id ? 'var(--success-color)' : undefined }}
                                            >
                                                <Copy size={14} />
                                            </button>
                                        </div>
                                    </td>
                                    <td style={{ fontWeight: 600, color: 'var(--text-primary)' }}>{task.title}</td>
                                    <td>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                            <div style={{ width: '24px', height: '24px', borderRadius: '50%', background: 'var(--primary-light)', color: 'var(--primary-color)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '10px', fontWeight: 'bold' }}>
                                                {task.assignee?.username?.charAt(0) || '?'}
                                            </div>
                                            {task.assignee?.username || '—'}
                                        </div>
                                    </td>
                                    <td>
                                        <span className={`status-badge ${getPriorityClass(task.priority)}`}>
                                            {task.priority === 'high' ? 'Высокий' : task.priority === 'medium' ? 'Средний' : 'Низкий'}
                                        </span>
                                    </td>
                                    <td style={{ color: 'var(--text-secondary)' }}>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                                            <Calendar size={14} />
                                            {task.created_at ? new Date(task.created_at).toLocaleDateString() : '—'}
                                        </div>
                                    </td>
                                    <td style={{ position: 'relative' }}>
                                        <button
                                            className="btn-icon"
                                            onClick={() => setActionMenuOpen(actionMenuOpen === task.id ? null : task.id)}
                                        >
                                            <MoreVertical size={18} />
                                        </button>

                                        {actionMenuOpen === task.id && (
                                            <div style={{
                                                position: 'absolute', right: '40px', top: '50%', transform: 'translateY(-50%)',
                                                background: 'var(--surface-color)', borderRadius: 'var(--radius-md)',
                                                boxShadow: 'var(--shadow-md)', border: '1px solid var(--border-color)',
                                                zIndex: 10, width: '160px', overflow: 'hidden'
                                            }}>
                                                {task.status !== 'done' && (
                                                    <button
                                                        style={{ width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: 'var(--success-color)' }}
                                                        onClick={() => {
                                                            handleCompleteTask(task.id);
                                                            setActionMenuOpen(null);
                                                        }}
                                                    >
                                                        <CheckCircle2 size={14} /> Выполнить
                                                    </button>
                                                )}
                                                <button
                                                    style={{
                                                        width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px',
                                                        color: 'var(--text-primary)', opacity: currentAdmin?.can_edit === false ? 0.5 : 1, cursor: currentAdmin?.can_edit === false ? 'not-allowed' : 'pointer'
                                                    }}
                                                    onClick={() => {
                                                        if (currentAdmin?.can_edit === false) return;
                                                        setSelectedTask(task);
                                                        setShowEditModal(true);
                                                        setActionMenuOpen(null);
                                                    }}
                                                    disabled={currentAdmin?.can_edit === false}
                                                >
                                                    <Edit size={14} /> Редактировать
                                                </button>
                                                <button
                                                    style={{
                                                        width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px',
                                                        color: 'var(--error-color)', opacity: currentAdmin?.can_edit === false ? 0.5 : 1, cursor: currentAdmin?.can_edit === false ? 'not-allowed' : 'pointer'
                                                    }}
                                                    onClick={() => {
                                                        if (currentAdmin?.can_edit === false) return;
                                                        handleDeleteTask(task.id);
                                                        setActionMenuOpen(null);
                                                    }}
                                                    disabled={currentAdmin?.can_edit === false}
                                                >
                                                    <Trash2 size={14} /> Удалить
                                                </button>
                                            </div>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                {/* Footer with pagination */}
                <div style={{
                    padding: '16px 24px', borderTop: '1px solid var(--border-color)',
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center'
                }}>
                    <div style={{ color: 'var(--text-secondary)', fontSize: '14px' }}>
                        Показано: {paginatedTasks.length} из {filteredTasks.length}
                    </div>
                    {renderPagination()}
                </div>
            </div>

            {selectedTasks.length > 0 && (
                <div className="bulk-actions-bar">
                    <span style={{ fontWeight: 600 }}>Выбрано: {selectedTasks.length}</span>
                    <div style={{ height: '20px', width: '1px', background: 'rgba(255,255,255,0.2)' }}></div>
                    <button onClick={handleDeleteSelected} style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#ff6b6b' }}>
                        <Trash2 size={18} /> Удалить выбранные
                    </button>
                </div>
            )}

            {showCreateModal && (
                <div className="modal-overlay" onClick={() => setShowCreateModal(false)}>
                    <div className="modal-content" onClick={e => e.stopPropagation()} style={{ maxWidth: '600px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                            <h3 style={{ fontSize: '20px', fontWeight: 'bold' }}>Создать задачу</h3>
                            <button onClick={() => setShowCreateModal(false)}><X size={24} color="var(--text-secondary)" /></button>
                        </div>
                        <form onSubmit={handleCreateTask}>
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                                <div className="input-group" style={{ gridColumn: 'span 2' }}>
                                    <label className="input-label">Название задачи</label>
                                    <input name="title" type="text" className="input-field" placeholder="Введите название" required />
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Приоритет</label>
                                    <select name="priority" className="input-field">
                                        <option value="low">Низкий</option>
                                        <option value="medium">Средний</option>
                                        <option value="high">Высокий</option>
                                    </select>
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Статус</label>
                                    <select name="status" className="input-field">
                                        <option value="todo">К выполнению</option>
                                        <option value="in_progress">В работе</option>
                                        <option value="done">Выполнено</option>
                                    </select>
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Исполнитель</label>
                                    <select name="user_id" className="input-field">
                                        <option value="">Без исполнителя</option>
                                        {usersList.map(u => (
                                            <option key={u.id} value={u.id}>{u.username}</option>
                                        ))}
                                    </select>
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Срок</label>
                                    <input name="due_date" type="date" className="input-field" />
                                </div>
                            </div>
                            <button type="submit" className="btn btn-primary" style={{ width: '100%', marginTop: '16px' }}>Создать</button>
                        </form>
                    </div>
                </div>
            )}

            {showEditModal && selectedTask && (
                <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
                    <div className="modal-content" onClick={e => e.stopPropagation()} style={{ maxWidth: '600px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                            <h3 style={{ fontSize: '20px', fontWeight: 'bold' }}>Редактировать задачу</h3>
                            <button onClick={() => setShowEditModal(false)}><X size={24} color="var(--text-secondary)" /></button>
                        </div>
                        <form onSubmit={handleUpdateTask}>
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                                <div className="input-group" style={{ gridColumn: 'span 2' }}>
                                    <label className="input-label">Название задачи</label>
                                    <input name="title" type="text" className="input-field" defaultValue={selectedTask.title} required />
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Приоритет</label>
                                    <select name="priority" className="input-field" defaultValue={selectedTask.priority}>
                                        <option value="low">Низкий</option>
                                        <option value="medium">Средний</option>
                                        <option value="high">Высокий</option>
                                    </select>
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Статус</label>
                                    <select name="status" className="input-field" defaultValue={selectedTask.status}>
                                        <option value="todo">К выполнению</option>
                                        <option value="in_progress">В работе</option>
                                        <option value="done">Выполнено</option>
                                    </select>
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Срок</label>
                                    <input name="due_date" type="date" className="input-field" defaultValue={selectedTask.due_date ? new Date(selectedTask.due_date).toISOString().split('T')[0] : ''} />
                                </div>
                            </div>
                            <div style={{ display: 'flex', gap: '12px', marginTop: '16px' }}>
                                <button type="button" className="btn btn-outline" style={{ flex: 1 }} onClick={() => setShowEditModal(false)}>Отмена</button>
                                <button type="submit" className="btn btn-primary" style={{ flex: 2 }}>Сохранить изменения</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default TasksPage;
