import React, { useState, useEffect, useMemo } from 'react';
import { useOutletContext } from 'react-router-dom';
import { supabase } from '../lib/supabaseClient';
import { Check, X, Clock, Mail, Shield, User, MoreVertical, Search, Trash2, Edit } from 'lucide-react';
import '../index.css';

const AdminPage = () => {
    const { searchTerm, updateSearchCount } = useOutletContext();
    const [activeTab, setActiveTab] = useState('active'); // 'active' or 'requests'
    const [activeAdmins, setActiveAdmins] = useState([]);
    const [requests, setRequests] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [notification, setNotification] = useState(null);
    const [adminSearch, setAdminSearch] = useState('');
    const [idSearch, setIdSearch] = useState('');
    const [dateFilter, setDateFilter] = useState('all');
    const [sortOrder, setSortOrder] = useState('new');
    const [actionMenuOpen, setActionMenuOpen] = useState(null);
    const [currentAdmin, setCurrentAdmin] = useState(null);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);

        // Fetch active admins (users with role = 'admin')
        const { data: admins, error: adminsError } = await supabase
            .from('users')
            .select('*')
            .eq('role', 'admin')
            .order('created_at', { ascending: false });

        // Fetch requests directly (they may not be users yet)
        const { data: reqs, error: reqsError } = await supabase
            .from('admin_requests')
            .select('*')
            .eq('status', 'pending')
            .order('created_at', { ascending: false });

        if (!adminsError) setActiveAdmins(admins || []);
        if (!reqsError) setRequests(reqs || []);

        const currentAdminId = localStorage.getItem('admin_user_id');
        if (currentAdminId) {
            const { data: current } = await supabase
                .from('users')
                .select('*')
                .eq('id', currentAdminId)
                .single();
            setCurrentAdmin(current);
        }

        setIsLoading(false);
    };

    const filteredAdmins = useMemo(() => {
        let result = [...activeAdmins];

        // Global search (from Topbar, though it's removed now, keeping for context context)
        if (searchTerm) {
            const lowerSearch = searchTerm.toLowerCase();
            result = result.filter(admin =>
                (admin.username?.toLowerCase() || '').includes(lowerSearch) ||
                (admin.email?.toLowerCase() || '').includes(lowerSearch)
            );
        }

        // Admin-specific search
        if (adminSearch) {
            const lowerSearch = adminSearch.toLowerCase();
            result = result.filter(admin =>
                (admin.username?.toLowerCase() || '').includes(lowerSearch) ||
                (admin.email?.toLowerCase() || '').includes(lowerSearch)
            );
        }

        // ID search
        if (idSearch) {
            result = result.filter(admin => admin.id?.toString().includes(idSearch));
        }

        // Date filter
        if (dateFilter !== 'all') {
            const now = new Date();
            const start = dateFilter === 'today' ? new Date(now.setHours(0, 0, 0, 0)) : new Date(now.setDate(now.getDate() - 7));
            result = result.filter(admin => new Date(admin.created_at) >= start);
        }

        return result;
    }, [activeAdmins, searchTerm, adminSearch, idSearch, dateFilter]);

    const filteredRequests = useMemo(() => {
        if (!searchTerm) return requests;
        const lowerSearch = searchTerm.toLowerCase();
        return requests.filter(req =>
            (req.name?.toLowerCase() || '').includes(lowerSearch) ||
            (req.email?.toLowerCase() || '').includes(lowerSearch)
        );
    }, [requests, searchTerm]);

    useEffect(() => {
        const count = activeTab === 'active' ? filteredAdmins.length : filteredRequests.length;
        updateSearchCount(searchTerm ? count : 0);
    }, [activeTab, filteredAdmins.length, filteredRequests.length, searchTerm, updateSearchCount]);

    const handleApprove = async (req) => {
        const { id, email, name, password } = req;

        // 1. Check if user already exists
        const { data: existingUser } = await supabase.from('users').select('id').eq('email', email).single();

        let userError;
        if (existingUser) {
            // Update role if exists
            const { error } = await supabase.from('users').update({ role: 'admin' }).eq('id', existingUser.id);
            userError = error;
        } else {
            // Create new user (removed 'status' and using 'username' correctly)
            const { error } = await supabase.from('users').insert([{
                email, username: name, password, role: 'admin', is_active: true, created_at: new Date().toISOString()
            }]);
            userError = error;
        }

        if (userError) {
            alert('Ошибка создания/обновления пользователя: ' + userError.message);
            return;
        }

        // 2. Update request status
        const { error: updateReqError } = await supabase.from('admin_requests').update({ status: 'approved' }).eq('id', id);

        if (!updateReqError) {
            setNotification({
                type: 'success',
                message: `Готово! Вы назначили ${name} администратором. Письмо отправлено с lowlowsite@gmail.com.`
            });
            fetchData();
        } else {
            alert('Ошибка при обновлении статуса заявки');
        }
        setTimeout(() => setNotification(null), 4000);
    };

    const handleReject = async (req) => {
        const { error } = await supabase.from('admin_requests').update({ status: 'rejected' }).eq('id', req.id);
        if (!error) {
            setNotification({
                type: 'error',
                message: `Отклонено. Пользователю ${req.nickname} сообщено о том, что он не назначен администратором.`
            });
            fetchData();
        }
        setTimeout(() => setNotification(null), 4000);
    };

    const handleBlockAdmin = async (id) => {
        if (window.confirm('Вы уверены, что хотите заблокировать этого администратора?')) {
            const { error } = await supabase.from('users').update({ is_active: false }).eq('id', id);
            if (!error) fetchData();
            else alert('Ошибка при блокировке: ' + error.message);
        }
    };

    const handleRemoveAdmin = async (id) => {
        if (window.confirm('Вы уверены, что хотите лишить этого пользователя прав администратора?')) {
            const { error } = await supabase.from('users').update({ role: 'user' }).eq('id', id);
            if (!error) fetchData();
            else alert('Ошибка при удалении прав: ' + error.message);
        }
    };

    return (
        <div>
            {notification && (
                <div style={{
                    position: 'fixed', top: '24px', right: '24px', padding: '16px 24px',
                    background: notification.type === 'success' ? '#4CAF50' : '#FF6B6B',
                    color: 'white', borderRadius: 'var(--radius-md)', boxShadow: 'var(--shadow-md)',
                    zIndex: 1000, animation: 'fadeIn 0.3s ease'
                }}>
                    {notification.message}
                </div>
            )}

            <div style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', marginBottom: '24px' }}>
                <div style={{ display: 'flex', background: 'var(--border-color)', padding: '4px', borderRadius: 'var(--radius-md)', gap: '4px' }}>
                    <button
                        className={`tab-btn ${activeTab === 'active' ? 'active' : ''}`}
                        onClick={() => setActiveTab('active')}
                        style={{
                            padding: '8px 16px', borderRadius: 'var(--radius-sm)', border: 'none',
                            background: activeTab === 'active' ? 'white' : 'transparent',
                            color: activeTab === 'active' ? 'var(--primary-color)' : 'var(--text-secondary)',
                            fontWeight: 600, cursor: 'pointer', fontSize: '14px'
                        }}
                    >
                        Действующие
                    </button>
                    <button
                        className={`tab-btn ${activeTab === 'requests' ? 'active' : ''}`}
                        onClick={() => setActiveTab('requests')}
                        style={{
                            padding: '8px 16px', borderRadius: 'var(--radius-sm)', border: 'none',
                            background: activeTab === 'requests' ? 'white' : 'transparent',
                            color: activeTab === 'requests' ? 'var(--primary-color)' : 'var(--text-secondary)',
                            fontWeight: 600, cursor: 'pointer', fontSize: '14px', position: 'relative'
                        }}
                    >
                        Заявки
                        {requests.length > 0 && (
                            <span style={{
                                position: 'absolute', top: '-4px', right: '-4px', background: 'var(--error-color)',
                                color: 'white', fontSize: '10px', width: '18px', height: '18px',
                                borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center'
                            }}>
                                {requests.length}
                            </span>
                        )}
                    </button>
                </div>
            </div>

            {activeTab === 'active' && (
                <div className="card-static" style={{ marginBottom: '24px' }}>
                    <div className="filter-bar">
                        <div className="filter-group" style={{ flex: 1 }}>
                            <label>Поиск по имени</label>
                            <div style={{ position: 'relative' }}>
                                <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                                <input
                                    type="text"
                                    className="filter-input"
                                    placeholder="Введите имя..."
                                    value={adminSearch}
                                    onChange={(e) => setAdminSearch(e.target.value)}
                                    style={{ paddingLeft: '36px', width: '100%' }}
                                />
                            </div>
                        </div>
                        <div className="filter-group" style={{ width: '180px' }}>
                            <label>Поиск по ID</label>
                            <div style={{ position: 'relative' }}>
                                <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                                <input
                                    type="text"
                                    className="filter-input"
                                    placeholder="ID..."
                                    value={idSearch}
                                    onChange={(e) => setIdSearch(e.target.value)}
                                    style={{ paddingLeft: '36px', width: '100%' }}
                                />
                            </div>
                        </div>
                        <div className="filter-group">
                            <label>Дата</label>
                            <select className="filter-select" value={dateFilter} onChange={(e) => setDateFilter(e.target.value)}>
                                <option value="all">Все</option>
                                <option value="today">Сегодня</option>
                                <option value="week">Неделя</option>
                            </select>
                        </div>
                    </div>
                </div>
            )}

            <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
                <div className="table-container">
                    <table>
                        <thead>
                            {activeTab === 'active' ? (
                                <tr>
                                    <th>Администратор</th>
                                    <th>Email адрес</th>
                                    <th>Дата назначения</th>
                                    <th style={{ width: '60px' }}></th>
                                </tr>
                            ) : (
                                <tr>
                                    <th>Кандидат</th>
                                    <th>Email адрес</th>
                                    <th>Дата заявки</th>
                                    <th style={{ width: '120px', textAlign: 'right', paddingRight: '24px' }}>Действия</th>
                                </tr>
                            )}
                        </thead>
                        <tbody>
                            {isLoading ? (
                                <tr><td colSpan="4" style={{ textAlign: 'center', padding: '48px' }}>Загрузка...</td></tr>
                            ) : activeTab === 'active' ? (
                                filteredAdmins.length === 0 ? (
                                    <tr><td colSpan="4" style={{ textAlign: 'center', padding: '48px' }}>Ничего не найдено</td></tr>
                                ) : filteredAdmins.map(admin => (
                                    <tr key={admin.id}>
                                        <td>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                                <div style={{
                                                    width: '36px', height: '36px', borderRadius: '50%',
                                                    background: 'var(--primary-light)', color: 'var(--primary-color)',
                                                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                    fontWeight: 'bold'
                                                }}>
                                                    {admin.username?.charAt(0) || <User size={18} />}
                                                </div>
                                                <div style={{ fontWeight: 600 }}>{admin.username}</div>
                                            </div>
                                        </td>
                                        <td style={{ color: 'var(--text-secondary)' }}>{admin.email}</td>
                                        <td style={{ color: 'var(--text-secondary)' }}>
                                            {admin.created_at ? new Date(admin.created_at).toLocaleDateString() : '—'}
                                        </td>
                                        <td style={{ position: 'relative' }}>
                                            <button
                                                className="btn-icon"
                                                onClick={() => setActionMenuOpen(actionMenuOpen === admin.id ? null : admin.id)}
                                            >
                                                <MoreVertical size={18} />
                                            </button>
                                            {actionMenuOpen === admin.id && (
                                                <div style={{
                                                    position: 'absolute', right: '40px', top: '50%', transform: 'translateY(-50%)',
                                                    background: 'var(--surface-color)', borderRadius: 'var(--radius-md)',
                                                    boxShadow: 'var(--shadow-md)', border: '1px solid var(--border-color)',
                                                    zIndex: 10, width: '160px', overflow: 'hidden'
                                                }}>
                                                    <button
                                                        style={{
                                                            width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px',
                                                            color: 'var(--text-primary)', opacity: currentAdmin?.can_edit === false ? 0.5 : 1, cursor: currentAdmin?.can_edit === false ? 'not-allowed' : 'pointer'
                                                        }}
                                                        onClick={() => {
                                                            if (currentAdmin?.can_edit === false) return;
                                                            // handleEditAdmin(admin);
                                                            setActionMenuOpen(null);
                                                        }}
                                                        disabled={currentAdmin?.can_edit === false}
                                                    >
                                                        <Edit size={14} /> Редактировать
                                                    </button>
                                                    <button
                                                        style={{
                                                            width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px',
                                                            color: 'var(--warning-color)'
                                                        }}
                                                        onClick={() => {
                                                            handleBlockAdmin(admin.id);
                                                            setActionMenuOpen(null);
                                                        }}
                                                    >
                                                        <Shield size={14} /> Заблокировать
                                                    </button>
                                                    <button
                                                        style={{
                                                            width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px',
                                                            color: 'var(--error-color)', opacity: currentAdmin?.can_edit === false ? 0.5 : 1, cursor: currentAdmin?.can_edit === false ? 'not-allowed' : 'pointer'
                                                        }}
                                                        onClick={() => {
                                                            if (currentAdmin?.can_edit === false) return;
                                                            handleRemoveAdmin(admin.id);
                                                            setActionMenuOpen(null);
                                                        }}
                                                        disabled={currentAdmin?.can_edit === false}
                                                    >
                                                        <Trash2 size={14} /> Удалить
                                                    </button>
                                                </div>
                                            )}
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                filteredRequests.length === 0 ? (
                                    <tr><td colSpan="4" style={{ textAlign: 'center', padding: '48px' }}>Нет заявок</td></tr>
                                ) : filteredRequests.map(req => (
                                    <tr key={req.id}>
                                        <td>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                                <div style={{ fontWeight: 600 }}>{req.name}</div>
                                            </div>
                                        </td>
                                        <td style={{ color: 'var(--text-secondary)' }}>{req.email}</td>
                                        <td style={{ color: 'var(--text-secondary)' }}>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                                                <Clock size={14} />
                                                {new Date(req.created_at).toLocaleDateString()}
                                            </div>
                                        </td>
                                        <td style={{ textAlign: 'right', paddingRight: '24px' }}>
                                            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '8px' }}>
                                                <button
                                                    onClick={() => handleReject(req)}
                                                    className="btn-icon"
                                                    style={{ background: 'rgba(255, 107, 107, 0.1)', color: 'var(--error-color)' }}
                                                >
                                                    <X size={18} />
                                                </button>
                                                <button
                                                    onClick={() => handleApprove(req)}
                                                    className="btn-icon"
                                                    style={{ background: 'rgba(76, 175, 80, 0.1)', color: 'var(--success-color)' }}
                                                >
                                                    <Check size={18} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                <div style={{
                    padding: '24px', borderTop: '1px solid var(--border-color)',
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center'
                }}>
                    <div style={{ color: 'var(--text-secondary)', fontSize: '14px' }}>
                        Показано {activeTab === 'active' ? filteredAdmins.length : filteredRequests.length} из {activeTab === 'active' ? activeAdmins.length : requests.length}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AdminPage;
