import React from 'react';
import { Outlet } from 'react-router-dom';
import Sidebar from '../components/Sidebar';
import Topbar from '../components/Topbar';

const Dashboard = ({ onLogout, session }) => {
    const [searchTerm, setSearchTerm] = React.useState('');
    const [searchCount, setSearchCount] = React.useState(0);

    const handleSearch = (term) => {
        setSearchTerm(term);
    };

    const updateSearchCount = (count) => {
        setSearchCount(count);
    };

    return (
        <div style={{ display: 'flex', minHeight: '100vh', background: 'var(--background-color)' }}>
            <Sidebar onLogout={onLogout} />
            <div style={{ flex: 1, marginLeft: '260px', display: 'flex', flexDirection: 'column' }}>
                <Topbar onSearch={handleSearch} searchCount={searchCount} session={session} />
                <main style={{ flex: 1, padding: '32px', overflowY: 'auto' }}>
                    <Outlet context={{ searchTerm, updateSearchCount }} />
                </main>
            </div>
        </div>
    );
};

export default Dashboard;
