import React, { useState, useEffect, useMemo } from 'react';
import { useOutletContext } from 'react-router-dom';
import { supabase } from '../lib/supabaseClient';
import { MoreVertical, Trash2, Edit, X, Phone, User, Shield, Info, Users, Search, ChevronLeft, ChevronRight } from 'lucide-react';
import '../index.css';

const ITEMS_PER_PAGE = 12;

const UsersPage = () => {
    const { searchTerm, updateSearchCount } = useOutletContext();
    const [selectedUsers, setSelectedUsers] = useState([]);
    const [isAllSelected, setIsAllSelected] = useState(false);
    const [users, setUsers] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    const [showCreateModal, setShowCreateModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const [selectedUser, setSelectedUser] = useState(null);
    const [actionMenuOpen, setActionMenuOpen] = useState(null);

    // Filters
    const [idSearch, setIdSearch] = useState('');
    const [clientSearch, setClientSearch] = useState('');
    const [dateFilter, setDateFilter] = useState('all');
    const [currentPage, setCurrentPage] = useState(1);

    useEffect(() => {
        fetchUsers();
    }, []);

    const fetchUsers = async () => {
        setIsLoading(true);
        const { data, error } = await supabase
            .from('users')
            .select('*')
            .order('created_at', { ascending: false });

        if (error) {
            console.error('Error fetching users:', error);
        } else {
            setUsers(data || []);
        }
        setIsLoading(false);
    };

    const getDateFilterStart = (filter) => {
        const now = new Date();
        switch (filter) {
            case 'today':
                return new Date(now.getFullYear(), now.getMonth(), now.getDate());
            case 'week':
                return new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
            case 'month':
                return new Date(now.getFullYear(), now.getMonth() - 1, now.getDate());
            case '6months':
                return new Date(now.getFullYear(), now.getMonth() - 6, now.getDate());
            case 'year':
                return new Date(now.getFullYear() - 1, now.getMonth(), now.getDate());
            default:
                return null;
        }
    };

    const filteredUsers = useMemo(() => {
        let result = users.filter(u => u.role !== 'admin');

        // Global search
        if (searchTerm) {
            const lowerSearch = searchTerm.toLowerCase();
            result = result.filter(user =>
                (user.username?.toLowerCase() || '').includes(lowerSearch) ||
                (user.email?.toLowerCase() || '').includes(lowerSearch) ||
                (user.role?.toLowerCase() || '').includes(lowerSearch)
            );
        }

        // Client name search
        if (clientSearch) {
            const lowerClient = clientSearch.toLowerCase();
            result = result.filter(user =>
                (user.username?.toLowerCase() || '').includes(lowerClient)
            );
        }

        // ID search
        if (idSearch) {
            result = result.filter(user =>
                user.id?.toString().toLowerCase().includes(idSearch.toLowerCase())
            );
        }

        // Date filter
        const dateStart = getDateFilterStart(dateFilter);
        if (dateStart) {
            result = result.filter(user => {
                const userDate = user.created_at ? new Date(user.created_at) : null;
                return userDate && userDate >= dateStart;
            });
        }

        return result;
    }, [users, searchTerm, clientSearch, dateFilter]);

    useEffect(() => {
        updateSearchCount(searchTerm ? filteredUsers.length : 0);
    }, [filteredUsers.length, searchTerm, updateSearchCount]);

    useEffect(() => {
        setCurrentPage(1);
    }, [clientSearch, idSearch, dateFilter, searchTerm]);

    const totalPages = Math.ceil(filteredUsers.length / ITEMS_PER_PAGE);
    const paginatedUsers = filteredUsers.slice(
        (currentPage - 1) * ITEMS_PER_PAGE,
        currentPage * ITEMS_PER_PAGE
    );

    // Stats calculations
    const stats = useMemo(() => {
        const now = new Date();
        const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        const newClients = users.filter(u => {
            const created = u.created_at ? new Date(u.created_at) : null;
            return created && created >= weekAgo;
        }).length;
        const activeClients = users.filter(u => u.is_active === true).length;
        const inactiveClients = users.filter(u => u.is_active === false).length;
        return { newClients, activeClients, inactiveClients, total: users.length };
    }, [users]);

    const handleSelectAll = () => {
        if (isAllSelected) {
            setSelectedUsers([]);
            setIsAllSelected(false);
        } else {
            setSelectedUsers(paginatedUsers.map(u => u.id));
            setIsAllSelected(true);
        }
    };

    const handleSelectUser = (id) => {
        setSelectedUsers(prev =>
            prev.includes(id) ? prev.filter(uid => uid !== id) : [...prev, id]
        );
        setIsAllSelected(false);
    };

    const handleBlockUser = async (user) => {
        if (window.confirm(`Вы уверены, что хотите заблокировать клиента ${user.username}? Он будет перемещен в архив.`)) {
            // First, copy to archive
            const { error: archiveError } = await supabase
                .from('users_archive')
                .insert([{
                    original_id: user.id,
                    username: user.username,
                    email: user.email,
                    phone: user.phone,
                    role: user.role,
                    metadata: { blocked_at: new Date().toISOString() }
                }]);

            if (archiveError) {
                alert('Ошибка при архивации: ' + archiveError.message);
                return;
            }

            // Then delete from main table
            const { error: deleteError } = await supabase.from('users').delete().eq('id', user.id);
            if (deleteError) alert('Ошибка удаления после архивации: ' + deleteError.message);
            else fetchUsers();
        }
    };

    const handleDeleteUser = async (id) => {
        if (window.confirm('Вы уверены, что хотите удалить этого клиента?')) {
            const { error } = await supabase.from('users').delete().eq('id', id);
            if (error) alert('Ошибка удаления: ' + error.message);
            else fetchUsers();
        }
    };

    const handleDeleteSelected = async () => {
        if (window.confirm(`Удалить выбранных клиентов (${selectedUsers.length})?`)) {
            const { error } = await supabase.from('users').delete().in('id', selectedUsers);
            if (error) alert('Ошибка удаления: ' + error.message);
            else {
                fetchUsers();
                setSelectedUsers([]);
                setIsAllSelected(false);
            }
        }
    };

    const handleUpdateUser = async (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const updates = Object.fromEntries(formData.entries());
        updates.is_active = updates.is_active === 'true'; // Convert string to boolean

        const { error } = await supabase.from('users').update(updates).eq('id', selectedUser.id);
        if (error) alert('Ошибка обновления: ' + error.message);
        else {
            setShowEditModal(false);
            fetchUsers();
        }
    };

    const handleCreateUser = async (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const newUser = Object.fromEntries(formData.entries());
        newUser.is_active = true; // New users are active by default

        const { error } = await supabase.from('users').insert([newUser]);
        if (error) alert('Ошибка создания: ' + error.message);
        else {
            setShowCreateModal(false);
            fetchUsers();
        }
    };

    const getStatusClass = (isActive) => {
        return isActive ? 'status-success' : 'status-error';
    };

    const getStatusLabel = (isActive) => {
        return isActive ? 'Активен' : 'Заблокирован';
    };

    const renderPagination = () => {
        if (totalPages <= 1) return null;
        const pages = [];
        const maxVisible = 5;
        let start = Math.max(1, currentPage - Math.floor(maxVisible / 2));
        let end = Math.min(totalPages, start + maxVisible - 1);
        if (end - start < maxVisible - 1) {
            start = Math.max(1, end - maxVisible + 1);
        }
        for (let i = start; i <= end; i++) {
            pages.push(i);
        }

        return (
            <div className="pagination">
                <button disabled={currentPage === 1} onClick={() => setCurrentPage(p => p - 1)}>
                    <ChevronLeft size={16} />
                </button>
                {start > 1 && (
                    <>
                        <button onClick={() => setCurrentPage(1)}>1</button>
                        {start > 2 && <span style={{ color: 'var(--text-secondary)', padding: '0 4px' }}>...</span>}
                    </>
                )}
                {pages.map(p => (
                    <button key={p} className={p === currentPage ? 'active' : ''} onClick={() => setCurrentPage(p)}>
                        {p}
                    </button>
                ))}
                {end < totalPages && (
                    <>
                        {end < totalPages - 1 && <span style={{ color: 'var(--text-secondary)', padding: '0 4px' }}>...</span>}
                        <button onClick={() => setCurrentPage(totalPages)}>{totalPages}</button>
                    </>
                )}
                <button disabled={currentPage === totalPages} onClick={() => setCurrentPage(p => p + 1)}>
                    <ChevronRight size={16} />
                </button>
            </div>
        );
    };

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '24px' }}>
                <div style={{ display: 'flex', gap: '12px' }}>
                    <button className="btn btn-primary" onClick={() => setShowCreateModal(true)}>
                        + Создать клиента
                    </button>
                </div>
            </div>

            {/* UI Updated: Removed stats row */}

            <div className="card-static" style={{ overflow: 'hidden' }}>
                {/* Filter Bar */}
                <div className="filter-bar">
                    <div className="filter-group" style={{ flex: 1, minWidth: '200px' }}>
                        <label>Поиск по клиенту</label>
                        <div style={{ position: 'relative' }}>
                            <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="text"
                                className="filter-input"
                                placeholder="Имя или никнейм..."
                                value={clientSearch}
                                onChange={(e) => setClientSearch(e.target.value)}
                                style={{ paddingLeft: '36px', width: '100%' }}
                            />
                        </div>
                    </div>
                    <div className="filter-group" style={{ width: '180px' }}>
                        <label>Поиск по ID</label>
                        <div style={{ position: 'relative' }}>
                            <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="text"
                                className="filter-input"
                                placeholder="ID пользователя..."
                                value={idSearch}
                                onChange={(e) => setIdSearch(e.target.value)}
                                style={{ paddingLeft: '36px', width: '100%' }}
                            />
                        </div>
                    </div>
                    <div className="filter-group">
                        <label>Дата</label>
                        <select
                            className="filter-select"
                            value={dateFilter}
                            onChange={(e) => setDateFilter(e.target.value)}
                        >
                            <option value="all">Все</option>
                            <option value="today">За Сегодня</option>
                            <option value="week">За Неделю</option>
                            <option value="month">За Месяц</option>
                            <option value="6months">За 6 Месяцев</option>
                            <option value="year">За 1 Год</option>
                        </select>
                    </div>
                </div>

                {/* Table */}
                <div className="table-container">
                    <table>
                        <thead>
                            <tr>
                                <th style={{ width: '40px', paddingLeft: '24px' }}>
                                    <input
                                        type="checkbox"
                                        checked={isAllSelected}
                                        onChange={handleSelectAll}
                                        style={{ width: '18px', height: '18px', accentColor: 'var(--primary-color)' }}
                                    />
                                </th>
                                <th>Клиент</th>
                                <th>Дата создания</th>
                                <th>Контакт</th>
                                <th>Email</th>
                                <th>Роль</th>
                                <th>Статус</th>
                                <th style={{ width: '60px' }}></th>
                            </tr>
                        </thead>
                        <tbody>
                            {isLoading ? (
                                <tr><td colSpan="8" style={{ textAlign: 'center', padding: '48px' }}>Загрузка...</td></tr>
                            ) : paginatedUsers.length === 0 ? (
                                <tr><td colSpan="8" style={{ textAlign: 'center', padding: '48px' }}>Ничего не найдено</td></tr>
                            ) : paginatedUsers.map((user) => (
                                <tr
                                    key={user.id}
                                    className={searchTerm && (user.name?.toLowerCase().includes(searchTerm.toLowerCase()) || user.email?.toLowerCase().includes(searchTerm.toLowerCase())) ? 'search-highlight' : ''}
                                    style={{ background: selectedUsers.includes(user.id) ? 'var(--primary-light)' : 'transparent' }}
                                >
                                    <td style={{ paddingLeft: '24px' }}>
                                        <input
                                            type="checkbox"
                                            checked={selectedUsers.includes(user.id)}
                                            onChange={() => handleSelectUser(user.id)}
                                            style={{ width: '18px', height: '18px', accentColor: 'var(--primary-color)' }}
                                        />
                                    </td>
                                    <td>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                            <div style={{
                                                width: '36px', height: '36px', borderRadius: '50%',
                                                background: 'white', border: '1px solid var(--border-color)',
                                                color: 'var(--primary-color)',
                                                display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                fontSize: '14px', fontWeight: 'bold'
                                            }}>
                                                {user.name?.charAt(0) || '?'}
                                            </div>
                                            <div style={{ fontWeight: 600, color: 'var(--text-primary)' }}>{user.name}</div>
                                        </div>
                                    </td>
                                    <td style={{ color: 'var(--text-secondary)' }}>
                                        {user.created_at ? new Date(user.created_at).toLocaleDateString() : '—'}
                                    </td>
                                    <td style={{ color: 'var(--text-secondary)' }}>{user.phone || '—'}</td>
                                    <td style={{ color: 'var(--text-secondary)' }}>{user.email}</td>
                                    <td>
                                        <span className={`status-badge ${user.role === 'admin' ? 'status-info' : 'status-neutral'}`}>
                                            {user.role === 'admin' ? 'Админ' : 'Клиент'}
                                        </span>
                                    </td>
                                    <td>
                                        <span className={`status-badge ${getStatusClass(user.is_active)}`}>
                                            {getStatusLabel(user.is_active)}
                                        </span>
                                    </td>
                                    <td style={{ position: 'relative' }}>
                                        <button
                                            className="btn-icon"
                                            onClick={() => setActionMenuOpen(actionMenuOpen === user.id ? null : user.id)}
                                        >
                                            <MoreVertical size={18} />
                                        </button>

                                        {actionMenuOpen === user.id && (
                                            <div style={{
                                                position: 'absolute', right: '40px', top: '50%', transform: 'translateY(-50%)',
                                                background: 'var(--surface-color)', borderRadius: 'var(--radius-md)',
                                                boxShadow: 'var(--shadow-md)', border: '1px solid var(--border-color)',
                                                zIndex: 10, width: '160px', overflow: 'hidden'
                                            }}>
                                                <button
                                                    style={{ width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: 'var(--text-primary)' }}
                                                    onClick={() => {
                                                        setSelectedUser(user);
                                                        setShowEditModal(true);
                                                        setActionMenuOpen(null);
                                                    }}
                                                >
                                                    <Edit size={14} /> Редактировать
                                                </button>
                                                <button
                                                    style={{ width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: 'var(--warning-color)' }}
                                                    onClick={() => {
                                                        handleBlockUser(user);
                                                        setActionMenuOpen(null);
                                                    }}
                                                >
                                                    <Shield size={14} /> Заблокировать
                                                </button>
                                                <button
                                                    style={{ width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: 'var(--error-color)' }}
                                                    onClick={() => {
                                                        handleDeleteUser(user.id);
                                                        setActionMenuOpen(null);
                                                    }}
                                                >
                                                    <Trash2 size={14} /> Удалить
                                                </button>
                                            </div>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                {/* Footer with pagination */}
                <div style={{
                    padding: '16px 24px', borderTop: '1px solid var(--border-color)',
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center'
                }}>
                    <div style={{ color: 'var(--text-secondary)', fontSize: '14px' }}>
                        Показано: {paginatedUsers.length} из {filteredUsers.length}
                    </div>
                    {renderPagination()}
                </div>
            </div>

            {selectedUsers.length > 0 && (
                <div className="bulk-actions-bar">
                    <span style={{ fontWeight: 600 }}>Выбрано: {selectedUsers.length}</span>
                    <div style={{ height: '20px', width: '1px', background: 'rgba(255,255,255,0.2)' }}></div>
                    <button onClick={handleDeleteSelected} style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#ff6b6b' }}>
                        <Trash2 size={18} /> Удалить выбранные
                    </button>
                </div>
            )}

            {showCreateModal && (
                <div className="modal-overlay" onClick={() => setShowCreateModal(false)}>
                    <div className="modal-content" onClick={e => e.stopPropagation()} style={{ maxWidth: '600px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                            <h3 style={{ fontSize: '20px', fontWeight: 'bold' }}>Создать клиента</h3>
                            <button onClick={() => setShowCreateModal(false)}><X size={24} color="var(--text-secondary)" /></button>
                        </div>
                        <form onSubmit={handleCreateUser}>
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                                <div className="input-group">
                                    <label className="input-label">Имя клиента</label>
                                    <input name="name" type="text" className="input-field" placeholder="Введите имя" required />
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Email</label>
                                    <input name="email" type="email" className="input-field" placeholder="email@example.com" required />
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Телефон</label>
                                    <input name="phone" type="text" className="input-field" placeholder="+7 (___) ___ __ __" />
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Роль</label>
                                    <select name="role" className="input-field">
                                        <option value="user">Пользователь</option>
                                        <option value="admin">Администратор</option>
                                    </select>
                                </div>
                            </div>
                            <button type="submit" className="btn btn-primary" style={{ width: '100%', marginTop: '16px' }}>Создать</button>
                        </form>
                    </div>
                </div>
            )}

            {showEditModal && selectedUser && (
                <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
                    <div className="modal-content" onClick={e => e.stopPropagation()} style={{ maxWidth: '700px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                <div style={{ width: '48px', height: '48px', borderRadius: '12px', background: 'var(--primary-light)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--primary-color)' }}>
                                    <User size={24} />
                                </div>
                                <div>
                                    <h3 style={{ fontSize: '20px', fontWeight: 'bold' }}>Редактировать профиль</h3>
                                    <p style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>ID: {selectedUser.id}</p>
                                </div>
                            </div>
                            <button onClick={() => setShowEditModal(false)}><X size={24} color="var(--text-secondary)" /></button>
                        </div>

                        <form onSubmit={handleUpdateUser}>
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
                                <div className="input-group">
                                    <label className="input-label">ФИО / Никнейм</label>
                                    <div style={{ position: 'relative' }}>
                                        <User size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                                        <input name="name" type="text" className="input-field" style={{ paddingLeft: '36px' }} defaultValue={selectedUser.name} />
                                    </div>
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Email адрес</label>
                                    <div style={{ position: 'relative' }}>
                                        <Info size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                                        <input name="email" type="email" className="input-field" style={{ paddingLeft: '36px' }} defaultValue={selectedUser.email} />
                                    </div>
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Номер телефона</label>
                                    <div style={{ position: 'relative' }}>
                                        <Phone size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                                        <input name="phone" type="text" className="input-field" style={{ paddingLeft: '36px' }} defaultValue={selectedUser.phone} />
                                    </div>
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Роль в системе</label>
                                    <div style={{ position: 'relative' }}>
                                        <Shield size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                                        <select name="role" className="input-field" style={{ paddingLeft: '36px' }} defaultValue={selectedUser.role}>
                                            <option value="user">Пользователь</option>
                                            <option value="admin">Администратор</option>
                                        </select>
                                    </div>
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Текущий статус</label>
                                    <select name="status" className="input-field" defaultValue={selectedUser.status}>
                                        <option value="active">Активен</option>
                                        <option value="inactive">Неактивен</option>
                                        <option value="blocked">Заблокирован</option>
                                    </select>
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Дата регистрации</label>
                                    <input type="text" className="input-field" defaultValue={selectedUser.created_at ? new Date(selectedUser.created_at).toLocaleDateString() : ''} disabled style={{ background: 'var(--background-color)', color: 'var(--text-secondary)' }} />
                                </div>
                            </div>

                            <div style={{ display: 'flex', gap: '12px', marginTop: '24px' }}>
                                <button type="button" className="btn btn-outline" style={{ flex: 1 }} onClick={() => setShowEditModal(false)}>Отмена</button>
                                <button type="submit" className="btn btn-primary" style={{ flex: 2 }}>Сохранить изменения</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default UsersPage;
