import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Mail, Lock, Loader2 } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';
import '../index.css';

import { verifyTOTP } from '../lib/mfaUtils';

const Login = () => {
    const [loading, setLoading] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const navigate = useNavigate();

    const [showOtp, setShowOtp] = useState(false);
    const [otpCode, setOtpCode] = useState('');
    const [pendingUser, setPendingUser] = useState(null);

    const handleLogin = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            const { data, error: queryError } = await supabase
                .from('users')
                .select('*')
                .eq('email', email.trim())
                .eq('password', password)
                .eq('role', 'admin')
                .limit(1);

            if (queryError || !data || data.length === 0) {
                setError('Неверный email или пароль, или нет прав администратора');
                setLoading(false);
                return;
            }

            const user = data[0];

            if (user.mfa_enabled && user.mfa_secret) {
                setPendingUser(user);
                setShowOtp(true);
                setLoading(false);
            } else {
                completeLogin(user);
            }
        } catch (err) {
            setError('Ошибка: ' + err.message);
            setLoading(false);
        }
    };

    const handleOtpVerify = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        const isValid = await verifyTOTP(pendingUser.mfa_secret, otpCode);
        if (isValid) {
            completeLogin(pendingUser);
        } else {
            setError('Неверный код. Попробуйте еще раз.');
            setLoading(false);
        }
    };

    const completeLogin = async (user) => {
        try {
            await supabase
                .from('users')
                .update({ last_login: new Date().toISOString() })
                .eq('id', user.id);

            localStorage.setItem('admin_user_id', user.id);
            window.dispatchEvent(new Event('session-changed'));
            navigate('/dashboard/overview');
        } catch (err) {
            console.warn('Login update failed:', err);
            navigate('/dashboard/overview');
        }
    };

    if (showOtp) {
        return (
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh', background: 'var(--background-color)' }}>
                <div className="card" style={{ width: '400px', textAlign: 'center' }}>
                    <h2 style={{ marginBottom: '16px' }}>Двухфакторная проверка</h2>
                    <p style={{ color: 'var(--text-secondary)', marginBottom: '24px', fontSize: '14px' }}>
                        Введите 6-значный код из приложения Authenticator
                    </p>

                    {error && <div style={{ color: 'var(--error-color)', marginBottom: '16px', fontSize: '14px' }}>{error}</div>}

                    <form onSubmit={handleOtpVerify}>
                        <div className="input-group">
                            <input
                                type="text"
                                className="input-field"
                                value={otpCode}
                                onChange={(e) => setOtpCode(e.target.value.replace(/\D/g, ''))}
                                maxLength={6}
                                style={{ textAlign: 'center', fontSize: '24px', letterSpacing: '8px' }}
                                placeholder="000000"
                                required
                                autoFocus
                            />
                        </div>
                        <button type="submit" className="btn btn-primary" style={{ width: '100%', marginTop: '16px' }} disabled={loading}>
                            {loading ? <Loader2 className="animate-spin" size={20} /> : 'Подтвердить'}
                        </button>
                        <button type="button" className="btn btn-outline" style={{ width: '100%', marginTop: '12px' }} onClick={() => setShowOtp(false)}>
                            Назад к входу
                        </button>
                    </form>
                </div>
            </div>
        );
    }

    const handleSubmit = handleLogin;

    return (
        <div style={{
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            minHeight: '100vh',
            background: 'var(--background-color)'
        }}>
            <div className="card" style={{ width: '400px', maxWidth: '90%' }}>
                <h2 style={{ textAlign: 'center', marginBottom: '24px', color: 'var(--text-primary)' }}>Вход</h2>

                {error && (
                    <div style={{
                        padding: '12px',
                        background: 'rgba(255, 107, 107, 0.1)',
                        color: 'var(--error-color)',
                        borderRadius: 'var(--radius-sm)',
                        marginBottom: '16px',
                        fontSize: '14px',
                        textAlign: 'center'
                    }}>
                        {error}
                    </div>
                )}

                <form onSubmit={handleSubmit}>
                    <div className="input-group">
                        <label className="input-label">Email</label>
                        <div style={{ position: 'relative' }}>
                            <Mail size={18} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="email"
                                className="input-field"
                                style={{ paddingLeft: '40px' }}
                                placeholder="email@example.com"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                required
                            />
                        </div>
                    </div>

                    <div className="input-group">
                        <label className="input-label">Пароль</label>
                        <div style={{ position: 'relative' }}>
                            <Lock size={18} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="password"
                                className="input-field"
                                style={{ paddingLeft: '40px' }}
                                placeholder="••••••••"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                required
                            />
                        </div>
                    </div>

                    <button
                        type="submit"
                        className="btn btn-primary"
                        style={{ width: '100%', marginTop: '8px' }}
                        disabled={loading}
                    >
                        {loading ? <Loader2 className="animate-spin" size={20} /> : 'Войти'}
                    </button>
                </form>

                <div style={{ marginTop: '24px', textAlign: 'center', fontSize: '14px', color: 'var(--text-secondary)' }}>
                    Нет аккаунта? <Link to="/register" style={{ color: 'var(--primary-color)', textDecoration: 'none', fontWeight: 600 }}>Подать заявку</Link>
                </div>
            </div>
        </div>
    );
};

export default Login;
