import React, { useState, useEffect, useMemo } from 'react';
import { useOutletContext } from 'react-router-dom';
import { supabase } from '../lib/supabaseClient';
import { ChevronLeft, ChevronRight, AlertCircle, Users, Clock, Info } from 'lucide-react';
import '../index.css';

const CalendarPage = () => {
    const { updateSearchCount } = useOutletContext();
    const [subtasks, setSubtasks] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [currentDate, setCurrentDate] = useState(new Date());
    const [selectedDate, setSelectedDate] = useState(new Date());

    useEffect(() => {
        updateSearchCount(0);
        fetchData();
    }, [updateSearchCount]);

    const fetchData = async () => {
        setIsLoading(true);
        // Fetch subtasks with their parent tasks
        const { data, error } = await supabase
            .from('subtasks')
            .select('*, tasks(id, title)')
            .order('created_at', { ascending: false });

        if (!error) {
            const mappedData = (data || []).map(st => ({
                ...st,
                task: st.tasks
            }));
            setSubtasks(mappedData);
        }
        setIsLoading(false);
    };

    const daysInMonth = (year, month) => new Date(year, month + 1, 0).getDate();
    const firstDayOfMonth = (year, month) => new Date(year, month, 1).getDay();

    const calendarGrid = useMemo(() => {
        const year = currentDate.getFullYear();
        const month = currentDate.getMonth();
        const totalDays = daysInMonth(year, month);
        const firstDay = (firstDayOfMonth(year, month) + 6) % 7;
        const grid = [];

        for (let i = 0; i < firstDay; i++) grid.push(null);
        for (let i = 1; i <= totalDays; i++) grid.push(new Date(year, month, i));

        return grid;
    }, [currentDate]);

    const eventsForDate = useMemo(() => {
        return subtasks.filter(st => {
            if (!st.created_at) return false;
            const date = new Date(st.created_at);
            return date.toDateString() === selectedDate.toDateString();
        });
    }, [subtasks, selectedDate]);

    const changeMonth = (offset) => {
        const next = new Date(currentDate);
        next.setMonth(next.getMonth() + offset);
        setCurrentDate(next);
    };

    if (isLoading) {
        return (
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '80px' }}>
                <div style={{ color: 'var(--text-secondary)', fontSize: '16px' }}>Загрузка календаря...</div>
            </div>
        );
    }

    return (
        <div style={{ padding: '32px' }}>
            <div className="calendar-block" style={{ minHeight: '600px' }}>
                <div className="calendar-left">
                    <div className="selected-date-info">
                        <div className="day-number">{selectedDate.getDate()}</div>
                        <div className="day-name">
                            {selectedDate.toLocaleDateString('ru-RU', { weekday: 'long', month: 'long', year: 'numeric' })}
                        </div>
                    </div>
                    <div style={{ marginTop: '24px' }}>
                        <h4 style={{ fontSize: '14px', marginBottom: '16px', color: 'var(--text-secondary)', fontWeight: 700 }}>ПОДЗАДАЧИ НА ДЕНЬ</h4>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                            {eventsForDate.length === 0 ? (
                                <div style={{ fontSize: '13px', color: 'var(--text-secondary)', padding: '16px', border: '1px dashed var(--border-color)', borderRadius: 'var(--radius-md)', textAlign: 'center' }}>
                                    Нет событий
                                </div>
                            ) : eventsForDate.map(event => (
                                <div key={event.id} className="event-card" style={{ background: 'var(--primary-light)', color: 'var(--primary-color)', border: '1px solid rgba(93, 124, 249, 0.2)', boxShadow: 'none' }}>
                                    <div className="time" style={{ color: 'var(--primary-color)', opacity: 0.8 }}>ID: #{event.id.toString().slice(0, 8)}</div>
                                    <div className="title" style={{ color: 'var(--text-primary)', marginBottom: '4px' }}>{event.title}</div>
                                    <div style={{ fontSize: '11px', display: 'flex', alignItems: 'center', gap: '4px', opacity: 0.7 }}>
                                        <Info size={10} /> Задача: {event.task?.title || '—'}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="calendar-middle">
                    <div className="calendar-header">
                        <h3 style={{ margin: 0, fontSize: '20px', fontWeight: 800 }}>Календарь подзадач</h3>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                            <button onClick={() => changeMonth(-1)} className="btn-icon"><ChevronLeft size={20} /></button>
                            <span style={{ fontWeight: 700, minWidth: '120px', textAlign: 'center', textTransform: 'capitalize' }}>
                                {currentDate.toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' })}
                            </span>
                            <button onClick={() => changeMonth(1)} className="btn-icon"><ChevronRight size={20} /></button>
                        </div>
                    </div>
                    <div className="calendar-grid">
                        {['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'].map(d => (
                            <div key={d} className="calendar-day-label">{d}</div>
                        ))}
                        {calendarGrid.map((date, i) => {
                            if (!date) return <div key={`empty-${i}`} />;
                            const isToday = date.toDateString() === new Date().toDateString();
                            const isSelected = date.toDateString() === selectedDate.toDateString();
                            const hasEvents = subtasks.some(st => st.created_at && new Date(st.created_at).toDateString() === date.toDateString());

                            return (
                                <div
                                    key={i}
                                    className={`calendar-day ${isToday ? 'today' : ''} ${isSelected ? 'selected' : ''} ${hasEvents ? 'has-event' : ''}`}
                                    onClick={() => setSelectedDate(date)}
                                    style={{ position: 'relative' }}
                                >
                                    {date.getDate()}
                                    {hasEvents && (
                                        <div style={{
                                            position: 'absolute', bottom: '6px', left: '50%', transform: 'translateX(-50%)',
                                            width: '6px', height: '6px', borderRadius: '50%', background: isSelected ? 'white' : 'var(--primary-color)'
                                        }}></div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>

                <div className="calendar-right">
                    <div>
                        <div className="activity-header">Информация</div>
                        <div style={{ padding: '20px', background: 'var(--background-color)', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-color)' }}>
                            <p style={{ fontSize: '13px', color: 'var(--text-secondary)', lineHeight: '1.6' }}>
                                В календаре отображаются все подзадачи. Выберите день, чтобы увидеть список подзадач и задачи, к которым они относятся.
                            </p>
                        </div>
                        <div style={{ marginTop: '32px' }}>
                            <h4 style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '16px', fontWeight: 700 }}>СТАТИСТИКА</h4>
                            <div className="activity-stats">
                                <div className="activity-stat-item">
                                    <span>Всего подзадач</span>
                                    <strong>{subtasks.length}</strong>
                                </div>
                                <div className="activity-stat-item">
                                    <span>На этот месяц</span>
                                    <strong>{subtasks.filter(st => st.created_at && new Date(st.created_at).getMonth() === currentDate.getMonth()).length}</strong>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CalendarPage;
