import React, { useState, useEffect, useMemo } from 'react';
import { useOutletContext } from 'react-router-dom';
import { supabase } from '../lib/supabaseClient';
import { MoreVertical, Filter, Layers, Trash2, Edit, X, CheckCircle2, Clock, ListTodo, Search } from 'lucide-react';
import '../index.css';

const SubtasksPage = () => {
    const { searchTerm, updateSearchCount } = useOutletContext();
    const [subtasks, setSubtasks] = useState([]);
    const [tasks, setTasks] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedSubtasks, setSelectedSubtasks] = useState([]);
    const [isAllSelected, setIsAllSelected] = useState(false);
    const [showCreateModal, setShowCreateModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const [selectedSubtask, setSelectedSubtask] = useState(null);
    const [actionMenuOpen, setActionMenuOpen] = useState(null);
    const [currentAdmin, setCurrentAdmin] = useState(null);
    const [subtaskSearch, setSubtaskSearch] = useState('');
    const [idSearch, setIdSearch] = useState('');
    const [dateFilter, setDateFilter] = useState('all');
    const [sortOrder, setSortOrder] = useState('az');

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);

        // Fetch subtasks with parent task title (explicit FK)
        const { data: subData, error: subError } = await supabase
            .from('subtasks')
            .select('*, task:tasks!task_id(id, title)')
            .order('created_at', { ascending: false });

        // Fetch tasks for selection in modals
        const { data: taskData, error: taskError } = await supabase
            .from('tasks')
            .select('id, title')
            .order('title');

        if (!subError) setSubtasks(subData || []);
        if (!taskError) setTasks(taskData || []);

        const currentAdminId = localStorage.getItem('admin_user_id');
        if (currentAdminId) {
            const { data: current } = await supabase
                .from('users')
                .select('*')
                .eq('id', currentAdminId)
                .single();
            setCurrentAdmin(current);
        }

        setIsLoading(false);
    };

    const filteredSubtasks = useMemo(() => {
        let result = [...subtasks];

        if (searchTerm) {
            const lowerSearch = searchTerm.toLowerCase();
            result = result.filter(sub =>
                (sub.title?.toLowerCase() || '').includes(lowerSearch) ||
                (sub.task?.title?.toLowerCase() || '').includes(lowerSearch)
            );
        }

        if (subtaskSearch) {
            const lowerFilter = subtaskSearch.toLowerCase();
            result = result.filter(sub => (sub.title?.toLowerCase() || '').includes(lowerFilter));
        }

        if (idSearch) {
            result = result.filter(sub => sub.id?.toString().includes(idSearch));
        }

        if (dateFilter !== 'all') {
            const now = new Date();
            const start = dateFilter === 'today' ? new Date(now.setHours(0, 0, 0, 0)) : new Date(now.setDate(now.getDate() - 7));
            result = result.filter(sub => new Date(sub.created_at) >= start);
        }

        if (sortOrder === 'az') result.sort((a, b) => a.title.localeCompare(b.title));
        else result.sort((a, b) => b.title.localeCompare(a.title));

        return result;
    }, [subtasks, searchTerm, subtaskSearch, idSearch, dateFilter, sortOrder]);

    useEffect(() => {
        updateSearchCount(searchTerm ? filteredSubtasks.length : 0);
    }, [filteredSubtasks.length, searchTerm, updateSearchCount]);

    const handleSelectAll = () => {
        if (isAllSelected) {
            setSelectedSubtasks([]);
            setIsAllSelected(false);
        } else {
            setSelectedSubtasks(filteredSubtasks.map(t => t.id));
            setIsAllSelected(true);
        }
    };

    const handleSelectSubtask = (id) => {
        setSelectedSubtasks(prev =>
            prev.includes(id) ? prev.filter(tid => tid !== id) : [...prev, id]
        );
        setIsAllSelected(false);
    };

    const handleDeleteSubtask = async (id) => {
        if (window.confirm('Вы уверены, что хотите удалить эту подзадачу?')) {
            const { error } = await supabase.from('subtasks').delete().eq('id', id);
            if (error) alert('Ошибка удаления: ' + error.message);
            else fetchData();
        }
    };

    const handleDeleteSelected = async () => {
        if (window.confirm(`Удалить выбранные подзадачи (${selectedSubtasks.length})?`)) {
            const { error } = await supabase.from('subtasks').delete().in('id', selectedSubtasks);
            if (error) alert('Ошибка удаления: ' + error.message);
            else {
                fetchData();
                setSelectedSubtasks([]);
                setIsAllSelected(false);
            }
        }
    };

    const handleCompleteSubtask = async (id) => {
        const { error } = await supabase.from('subtasks').update({ status: 'done' }).eq('id', id);
        if (error) alert('Ошибка: ' + error.message);
        else fetchData();
    };

    const handleCreateSubtask = async (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const newSubtask = Object.fromEntries(formData.entries());

        // Handle duration_minutes if needed, for now just store duration as text if schema allowed
        // But schema says duration_minutes INTEGER. Let's assume input is in minutes for now.
        if (newSubtask.duration_minutes) {
            newSubtask.duration_minutes = parseInt(newSubtask.duration_minutes);
        }

        const { error } = await supabase.from('subtasks').insert([newSubtask]);
        if (error) alert('Ошибка создания: ' + error.message);
        else {
            setShowCreateModal(false);
            fetchData();
        }
    };

    const handleUpdateSubtask = async (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const updates = Object.fromEntries(formData.entries());

        if (updates.duration_minutes) {
            updates.duration_minutes = parseInt(updates.duration_minutes);
        }

        const { error } = await supabase.from('subtasks').update(updates).eq('id', selectedSubtask.id);
        if (error) alert('Ошибка обновления: ' + error.message);
        else {
            setShowEditModal(false);
            fetchData();
        }
    };

    const getStatusClass = (status) => {
        switch (status) {
            case 'done': return 'status-success';
            case 'in_progress': return 'status-info';
            case 'todo': return 'status-warning';
            default: return 'status-neutral';
        }
    };

    const getStatusLabel = (status) => {
        switch (status) {
            case 'done': return 'Завершено';
            case 'in_progress': return 'В работе';
            case 'todo': return 'К выполнению';
            default: return status || '—';
        }
    };

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '24px' }}>
                <div style={{ display: 'flex', gap: '12px' }}>
                    <button className="btn btn-primary" onClick={() => setShowCreateModal(true)}>
                        + Создать подзадачу
                    </button>
                </div>
            </div>

            <div className="card-static" style={{ marginBottom: '24px' }}>
                <div className="filter-bar">
                    <div className="filter-group" style={{ flex: 1 }}>
                        <label>Поиск по подзадачам</label>
                        <div style={{ position: 'relative' }}>
                            <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="text"
                                className="filter-input"
                                placeholder="Найти подзадачу..."
                                value={subtaskSearch}
                                onChange={(e) => setSubtaskSearch(e.target.value)}
                                style={{ paddingLeft: '36px', width: '100%' }}
                            />
                        </div>
                    </div>
                    <div className="filter-group" style={{ width: '180px' }}>
                        <label>Поиск по ID</label>
                        <div style={{ position: 'relative' }}>
                            <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="text"
                                className="filter-input"
                                placeholder="ID..."
                                value={idSearch}
                                onChange={(e) => setIdSearch(e.target.value)}
                                style={{ paddingLeft: '36px', width: '100%' }}
                            />
                        </div>
                    </div>
                    <div className="filter-group">
                        <label>Дата</label>
                        <select className="filter-select" value={dateFilter} onChange={(e) => setDateFilter(e.target.value)}>
                            <option value="all">Все</option>
                            <option value="today">Сегодня</option>
                            <option value="week">Неделя</option>
                        </select>
                    </div>
                    <div className="filter-group">
                        <label>Сортировка</label>
                        <select className="filter-select" value={sortOrder} onChange={(e) => setSortOrder(e.target.value)}>
                            <option value="az">А-Я</option>
                            <option value="za">Я-А</option>
                        </select>
                    </div>
                </div>
            </div>

            <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
                <div className="table-container">
                    <table>
                        <thead>
                            <tr>
                                <th style={{ width: '40px', paddingLeft: '24px' }}>
                                    <input
                                        type="checkbox"
                                        checked={isAllSelected}
                                        onChange={handleSelectAll}
                                        style={{ width: '18px', height: '18px', accentColor: 'var(--primary-color)' }}
                                    />
                                </th>
                                <th>Название</th>
                                <th>Родительская задача</th>
                                <th>Длительность</th>
                                <th>Статус</th>
                                <th style={{ width: '60px' }}></th>
                            </tr>
                        </thead>
                        <tbody>
                            {isLoading ? (
                                <tr><td colSpan="6" style={{ textAlign: 'center', padding: '48px' }}>Загрузка...</td></tr>
                            ) : filteredSubtasks.length === 0 ? (
                                <tr><td colSpan="6" style={{ textAlign: 'center', padding: '48px' }}>Ничего не найдено</td></tr>
                            ) : filteredSubtasks.map((task) => (
                                <tr
                                    key={task.id}
                                    className={searchTerm && (task.title?.toLowerCase().includes(searchTerm.toLowerCase())) ? 'search-highlight' : ''}
                                    style={{ background: selectedSubtasks.includes(task.id) ? 'var(--primary-light)' : 'transparent' }}
                                >
                                    <td style={{ paddingLeft: '24px' }}>
                                        <input
                                            type="checkbox"
                                            checked={selectedSubtasks.includes(task.id)}
                                            onChange={() => handleSelectSubtask(task.id)}
                                            style={{ width: '18px', height: '18px', accentColor: 'var(--primary-color)' }}
                                        />
                                    </td>
                                    <td style={{ fontWeight: 600, color: 'var(--text-primary)' }}>{task.title}</td>
                                    <td>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--text-secondary)' }}>
                                            <Layers size={14} />
                                            {task.task?.title || '—'}
                                        </div>
                                    </td>
                                    <td style={{ color: 'var(--text-secondary)' }}>
                                        {task.duration_minutes ? `${task.duration_minutes} мин` : '—'}
                                    </td>
                                    <td>
                                        <span className={`status-badge ${getStatusClass(task.status)}`}>
                                            {getStatusLabel(task.status)}
                                        </span>
                                    </td>
                                    <td style={{ position: 'relative' }}>
                                        <button
                                            className="btn-icon"
                                            onClick={() => setActionMenuOpen(actionMenuOpen === task.id ? null : task.id)}
                                        >
                                            <MoreVertical size={18} />
                                        </button>

                                        {actionMenuOpen === task.id && (
                                            <div style={{
                                                position: 'absolute', right: '40px', top: '50%', transform: 'translateY(-50%)',
                                                background: 'var(--surface-color)', borderRadius: 'var(--radius-md)',
                                                boxShadow: 'var(--shadow-md)', border: '1px solid var(--border-color)',
                                                zIndex: 10, width: '160px', overflow: 'hidden'
                                            }}>
                                                {task.status !== 'done' && (
                                                    <button
                                                        style={{ width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: 'var(--success-color)' }}
                                                        onClick={() => {
                                                            handleCompleteSubtask(task.id);
                                                            setActionMenuOpen(null);
                                                        }}
                                                    >
                                                        <CheckCircle2 size={14} /> Выполнить
                                                    </button>
                                                )}
                                                <button
                                                    style={{
                                                        width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px',
                                                        color: 'var(--text-primary)', opacity: currentAdmin?.can_edit === false ? 0.5 : 1, cursor: currentAdmin?.can_edit === false ? 'not-allowed' : 'pointer'
                                                    }}
                                                    onClick={() => {
                                                        if (currentAdmin?.can_edit === false) return;
                                                        setSelectedSubtask(task);
                                                        setShowEditModal(true);
                                                        setActionMenuOpen(null);
                                                    }}
                                                    disabled={currentAdmin?.can_edit === false}
                                                >
                                                    <Edit size={14} /> Редактировать
                                                </button>
                                                <button
                                                    style={{
                                                        width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px',
                                                        color: 'var(--error-color)', opacity: currentAdmin?.can_edit === false ? 0.5 : 1, cursor: currentAdmin?.can_edit === false ? 'not-allowed' : 'pointer'
                                                    }}
                                                    onClick={() => {
                                                        if (currentAdmin?.can_edit === false) return;
                                                        handleDeleteSubtask(task.id);
                                                        setActionMenuOpen(null);
                                                    }}
                                                    disabled={currentAdmin?.can_edit === false}
                                                >
                                                    <Trash2 size={14} /> Удалить
                                                </button>
                                            </div>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                <div style={{
                    padding: '24px', borderTop: '1px solid var(--border-color)',
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center'
                }}>
                    <div style={{ color: 'var(--text-secondary)', fontSize: '14px' }}>
                        Показано: {filteredSubtasks.length} из {subtasks.length}
                    </div>
                </div>
            </div>

            {
                selectedSubtasks.length > 0 && (
                    <div className="bulk-actions-bar">
                        <span style={{ fontWeight: 600 }}>Выбрано: {selectedSubtasks.length}</span>
                        <div style={{ height: '20px', width: '1px', background: 'rgba(255,255,255,0.2)' }}></div>
                        <button onClick={handleDeleteSelected} style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#ff6b6b' }}>
                            <Trash2 size={18} /> Удалить выбранные
                        </button>
                    </div>
                )
            }

            {
                showCreateModal && (
                    <div className="modal-overlay" onClick={() => setShowCreateModal(false)}>
                        <div className="modal-content" onClick={e => e.stopPropagation()} style={{ maxWidth: '600px' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                                <h3 style={{ fontSize: '20px', fontWeight: 'bold' }}>Создать подзадачу</h3>
                                <button onClick={() => setShowCreateModal(false)}><X size={24} color="var(--text-secondary)" /></button>
                            </div>
                            <form onSubmit={handleCreateSubtask}>
                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                                    <div className="input-group" style={{ gridColumn: 'span 2' }}>
                                        <label className="input-label">Название</label>
                                        <input name="title" type="text" className="input-field" placeholder="Введите название" required />
                                    </div>
                                    <div className="input-group">
                                        <label className="input-label">Родительская задача</label>
                                        <select name="task_id" className="input-field" required>
                                            <option value="">Выберите задачу</option>
                                            {tasks.map(t => (
                                                <option key={t.id} value={t.id}>{t.title}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="input-group">
                                        <label className="input-label">Длительность (мин)</label>
                                        <input name="duration_minutes" type="number" className="input-field" placeholder="Например: 45" />
                                    </div>
                                    <div className="input-group">
                                        <label className="input-label">Статус</label>
                                        <select name="status" className="input-field">
                                            <option value="todo">К выполнению</option>
                                            <option value="in_progress">В работе</option>
                                            <option value="done">Выполнено</option>
                                        </select>
                                    </div>
                                </div>
                                <button type="submit" className="btn btn-primary" style={{ width: '100%', marginTop: '16px' }}>Создать</button>
                            </form>
                        </div>
                    </div>
                )
            }

            {
                showEditModal && selectedSubtask && (
                    <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
                        <div className="modal-content" onClick={e => e.stopPropagation()} style={{ maxWidth: '600px' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                                <h3 style={{ fontSize: '20px', fontWeight: 'bold' }}>Редактировать подзадачу</h3>
                                <button onClick={() => setShowEditModal(false)}><X size={24} color="var(--text-secondary)" /></button>
                            </div>
                            <form onSubmit={handleUpdateSubtask}>
                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                                    <div className="input-group" style={{ gridColumn: 'span 2' }}>
                                        <label className="input-label">Название</label>
                                        <input name="title" type="text" className="input-field" defaultValue={selectedSubtask.title} required />
                                    </div>
                                    <div className="input-group">
                                        <label className="input-label">Родительская задача</label>
                                        <select name="task_id" className="input-field" defaultValue={selectedSubtask.task_id} required>
                                            {tasks.map(t => (
                                                <option key={t.id} value={t.id}>{t.title}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="input-group">
                                        <label className="input-label">Длительность (мин)</label>
                                        <input name="duration_minutes" type="number" className="input-field" defaultValue={selectedSubtask.duration_minutes} />
                                    </div>
                                    <div className="input-group">
                                        <label className="input-label">Статус</label>
                                        <select name="status" className="input-field" defaultValue={selectedSubtask.status}>
                                            <option value="todo">К выполнению</option>
                                            <option value="in_progress">В работе</option>
                                            <option value="done">Выполнено</option>
                                        </select>
                                    </div>
                                </div>
                                <div style={{ display: 'flex', gap: '12px', marginTop: '16px' }}>
                                    <button type="button" className="btn btn-outline" style={{ flex: 1 }} onClick={() => setShowEditModal(false)}>Отмена</button>
                                    <button type="submit" className="btn btn-primary" style={{ flex: 2 }}>Сохранить изменения</button>
                                </div>
                            </form>
                        </div>
                    </div>
                )
            }
        </div >
    );
};

export default SubtasksPage;
