import { NavLink } from 'react-router-dom';
import {
    LayoutDashboard,
    Users,
    ShieldCheck,
    Briefcase,
    CheckSquare,
    Settings,
    LogOut,
    ClipboardList,
    Layers
} from 'lucide-react';
import '../index.css';

const Sidebar = ({ onLogout }) => {
    const navItems = [
        {
            group: 'ОСНОВНОЕ', items: [
                { path: '/dashboard/overview', label: 'Дашборд', icon: LayoutDashboard },
                { path: '/dashboard/calendar', label: 'Календарь', icon: ClipboardList }
            ]
        },
        {
            group: 'ПОЛЬЗОВАТЕЛИ', items: [
                { path: '/dashboard/users', label: 'Клиенты', icon: Users },
                { path: '/dashboard/admin', label: 'Администраторы', icon: ShieldCheck }
            ]
        },
        {
            group: 'РАБОТА', items: [
                { path: '/dashboard/teams', label: 'Команды', icon: Briefcase },
                { path: '/dashboard/tasks', label: 'Задачи', icon: CheckSquare },
                { path: '/dashboard/subtasks', label: 'Подзадачи', icon: Layers }
            ]
        }
    ];

    return (
        <div style={{
            width: '260px',
            background: 'var(--surface-color)',
            borderRight: '1px solid var(--border-color)',
            display: 'flex',
            flexDirection: 'column',
            position: 'fixed',
            height: '100vh',
            zIndex: 100
        }}>
            <div style={{ padding: '32px 24px', borderBottom: '1px solid var(--border-color)' }}>
                <h1 style={{ fontSize: '18px', fontWeight: 800, color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '12px', letterSpacing: '-0.02em' }}>
                    <div style={{ width: '32px', height: '32px', background: 'var(--primary-gradient)', borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white' }}>
                        <ShieldCheck size={20} />
                    </div>
                    Админ панель
                </h1>
            </div>

            <nav style={{ flex: 1, padding: '16px 12px', overflowY: 'auto' }}>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                    {navItems.map((group, idx) => (
                        <div key={idx}>
                            <div className="sidebar-category-header">
                                {group.group}
                            </div>
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '2px' }}>
                                {group.items.map((item) => (
                                    <NavLink
                                        key={item.path}
                                        to={item.path}
                                        className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}
                                    >
                                        <item.icon size={18} />
                                        <span>{item.label}</span>
                                    </NavLink>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
            </nav>

            <div style={{ padding: '24px', borderTop: '1px solid var(--border-color)', display: 'flex', flexDirection: 'column', gap: '8px' }}>
                <NavLink to="/dashboard/settings" className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}>
                    <Settings size={18} />
                    <span>Настройки</span>
                </NavLink>
                <button
                    onClick={onLogout}
                    className="sidebar-link"
                    style={{
                        border: 'none',
                        background: 'transparent',
                        width: '100%',
                        textAlign: 'left',
                        cursor: 'pointer',
                        color: 'var(--error-color)'
                    }}
                >
                    <LogOut size={18} />
                    <span>Выйти</span>
                </button>
            </div>
        </div>
    );
};

export default Sidebar;
