import React, { useState, useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Search, Command } from 'lucide-react';

const Topbar = ({ onSearch, searchCount, session }) => {
    const location = useLocation();
    const navigate = useNavigate();
    const [searchValue, setSearchValue] = useState('');
    const [isCommandMode, setIsCommandMode] = useState(false);
    const [isFocused, setIsFocused] = useState(false);
    const inputRef = useRef(null);

    // Get user info from session (fetched from Supabase)
    const userName = session?.full_name || session?.username || session?.email?.split('@')[0] || 'Админ';
    const userInitials = userName.split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);

    // Focus input on '/' key press
    useEffect(() => {
        const handleKeyDown = (e) => {
            if (e.key === '/' && document.activeElement !== inputRef.current) {
                e.preventDefault();
                inputRef.current.focus();
                setSearchValue('/');
                setIsCommandMode(true);
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, []);

    const handleSearchChange = (e) => {
        const value = e.target.value;
        setSearchValue(value);
        setIsCommandMode(value.startsWith('/'));

        if (!value.startsWith('/')) {
            onSearch(value);
        }
    };

    const getPageTitle = () => {
        const path = location.pathname.split('/').pop();
        const titles = {
            'overview': 'Дашборд',
            'users': 'Клиенты',
            'teams': 'Команды',
            'admin': 'Администраторы',
            'tasks': 'Задачи',
            'subtasks': 'Подзадачи',
            'settings': 'Настройки'
        };
        return titles[path] || 'Панель управления';
    };

    const handleKeyDown = (e) => {
        if (e.key === 'Enter') {
            if (isCommandMode) {
                const cmd = searchValue.split(' ')[0];
                if (['/overview', '/users', '/teams', '/admin', '/tasks', '/subtasks', '/settings'].includes(cmd)) {
                    navigate(`/dashboard${cmd.substring(0)}`);
                    setSearchValue('');
                    setIsCommandMode(false);
                    onSearch('');
                }
            }
        }
        if (e.key === 'Escape') {
            setSearchValue('');
            setIsCommandMode(false);
            onSearch('');
            inputRef.current.blur();
        }
    };

    const commands = [
        { id: '/overview', label: '/overview' },
        { id: '/users', label: '/users' },
        { id: '/teams', label: '/teams' },
        { id: '/admin', label: '/admin' },
        { id: '/tasks', label: '/tasks' },
        { id: '/subtasks', label: '/subtasks' },
        { id: '/settings', label: '/settings' }
    ];

    const filteredCommands = isCommandMode
        ? commands.filter(c => c.id.startsWith(searchValue.split(' ')[0]))
        : [];

    return (
        <div style={{
            padding: '16px 32px',
            borderBottom: '1px solid var(--border-color)',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            background: 'var(--surface-color)',
            position: 'sticky',
            top: 0,
            zIndex: 10
        }}>
            <div>
                {/* No title here, requested to be removed from pages, Topbar can stay empty or show breadcrumbs if needed, but keeping it simple for now */}
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: '24px' }}>
                {/* User (data from Supabase session) */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <div style={{
                        width: '40px',
                        height: '40px',
                        borderRadius: '12px',
                        background: 'var(--primary-light)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: 'var(--primary-color)',
                        fontWeight: 'bold',
                        fontSize: '14px'
                    }}>
                        {userInitials}
                    </div>
                    <div>
                        <div style={{ fontSize: '14px', fontWeight: 600, color: 'var(--text-primary)' }}>
                            {userName}
                        </div>
                        <div style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>
                            Админ
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Topbar;
