import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabaseClient';
import { User, Mail, Phone, Lock, Shield, AlertTriangle, LogOut, Archive, X, Loader2, CheckCircle2, QrCode } from 'lucide-react';
import { generateTOTPSecret, verifyTOTP } from '../lib/mfaUtils';
import '../index.css';

const SettingsPage = () => {
    const [user, setUser] = useState({ username: '', email: '', phone: '' });
    const [is2FAEnabled, setIs2FAEnabled] = useState(false);
    const [isEditing, setIsEditing] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    // MFA Enrollment State
    const [showMfaModal, setShowMfaModal] = useState(false);
    const [mfaData, setMfaData] = useState(null);
    const [verifyCode, setVerifyCode] = useState('');
    const [mfaError, setMfaError] = useState('');
    const [isEnrolling, setIsEnrolling] = useState(false);
    const [notificationMessage, setNotificationMessage] = useState(null);

    useEffect(() => {
        fetchUserData();
        checkMfaStatus();
    }, []);

    const fetchUserData = async () => {
        const adminId = localStorage.getItem('admin_user_id');
        if (!adminId) {
            setIsLoading(false);
            return;
        }

        const { data: userData, error } = await supabase
            .from('users')
            .select('*')
            .eq('id', adminId)
            .single();

        if (!error && userData) {
            setUser({
                username: userData.username || '',
                email: userData.email || '',
                phone: userData.phone || ''
            });
            setIs2FAEnabled(userData.mfa_enabled || false);
        }
        setIsLoading(false);
    };

    const checkMfaStatus = async () => {
        // Since we are using manual auth, we rely on the users table flag
        // instead of supabase.auth.mfa
    };

    const handleSave = async (e) => {
        e.preventDefault();
        const adminId = localStorage.getItem('admin_user_id');
        const { error } = await supabase
            .from('users')
            .update({ username: user.username, phone: user.phone })
            .eq('id', adminId);

        if (error) alert('Ошибка: ' + error.message);
        else {
            setIsEditing(false);
            alert('Данные обновлены');
        }
    };

    const toggle2FA = async () => {
        if (!is2FAEnabled) {
            startMfaEnrollment();
        } else {
            if (window.confirm('Вы уверены, что хотите отключить 2FA? Это снизит безопасность аккаунта.')) {
                setIsLoading(true);
                const { error } = await supabase.from('users').update({ mfa_enabled: false, mfa_secret: null }).eq('email', user.email);
                if (error) alert('Ошибка: ' + error.message);
                else setIs2FAEnabled(false);
                setIsLoading(false);
            }
        }
    };

    const startMfaEnrollment = async () => {
        setIsEnrolling(true);
        setMfaError('');

        // Generate secret manually
        const secret = generateTOTPSecret();
        const qrCodeUri = `otpauth://totp/Tomoroki:${user.email}?secret=${secret}&issuer=Tomoroki`;

        setMfaData({
            secret: secret,
            otpauth_url: qrCodeUri
        });

        setShowMfaModal(true);
        setIsEnrolling(false);
    };

    const handleVerifyEnrollment = async (e) => {
        e.preventDefault();
        setMfaError('');
        setIsEnrolling(true);

        const isValid = await verifyTOTP(mfaData.secret, verifyCode);

        if (!isValid) {
            setMfaError('Неверный код. Проверьте время на телефоне и попробуйте еще раз.');
            setIsEnrolling(false);
        } else {
            // Save to DB
            const { error } = await supabase
                .from('users')
                .update({
                    mfa_enabled: true,
                    mfa_secret: mfaData.secret
                })
                .eq('email', user.email);

            if (error) {
                setMfaError('Ошибка сохранения: ' + error.message);
                setIsEnrolling(false);
                return;
            }

            setIs2FAEnabled(true);
            setShowMfaModal(false);
            setMfaData(null);
            setVerifyCode('');
            setIsEnrolling(false);
            alert('Двухфакторная аутентификация успешно включена!');
        }
    };

    if (isLoading) return <div style={{ textAlign: 'center', padding: '100px', color: 'white' }}>Загрузка...</div>;

    return (
        <div style={{ maxWidth: '800px', margin: '0 auto', position: 'relative' }}>
            {notificationMessage && (
                <div style={{
                    position: 'fixed',
                    top: '24px',
                    right: '24px',
                    background: 'var(--primary-color)',
                    color: 'white',
                    padding: '16px 24px',
                    borderRadius: '12px',
                    boxShadow: 'var(--shadow-lg)',
                    zIndex: 1000,
                    display: 'flex',
                    alignItems: 'center',
                    gap: '12px',
                    animation: 'slideIn 0.3s ease'
                }}>
                    <Shield size={20} />
                    <div style={{ fontWeight: 500 }}>{notificationMessage}</div>
                </div>
            )}
            <h2 style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '24px' }}>Настройки</h2>

            {/* Personal Data */}
            <div className="card" style={{ marginBottom: '24px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                    <h3 style={{ fontSize: '18px', fontWeight: 600 }}>Личные данные</h3>
                    <button
                        className={`btn ${isEditing ? 'btn-primary' : 'btn-outline'}`}
                        onClick={(e) => isEditing ? handleSave(e) : setIsEditing(true)}
                    >
                        {isEditing ? 'Сохранить' : 'Редактировать'}
                    </button>
                </div>

                <form>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px' }}>
                        <div className="input-group">
                            <label className="input-label">Никнейм</label>
                            <div style={{ position: 'relative' }}>
                                <User size={18} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                                <input
                                    type="text"
                                    className="input-field"
                                    style={{ paddingLeft: '40px' }}
                                    value={user.username}
                                    disabled={!isEditing}
                                    onChange={(e) => setUser({ ...user, username: e.target.value })}
                                />
                            </div>
                        </div>

                        <div className="input-group">
                            <label className="input-label">Email</label>
                            <div style={{ position: 'relative' }}>
                                <Mail size={18} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                                <input
                                    type="email"
                                    className="input-field"
                                    style={{ paddingLeft: '40px' }}
                                    value={user.email}
                                    disabled={true}
                                />
                            </div>
                        </div>

                        <div className="input-group">
                            <label className="input-label">Телефон</label>
                            <div style={{ position: 'relative' }}>
                                <Phone size={18} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                                <input
                                    type="tel"
                                    className="input-field"
                                    style={{ paddingLeft: '40px' }}
                                    value={user.phone}
                                    disabled={!isEditing}
                                    onChange={(e) => setUser({ ...user, phone: e.target.value })}
                                />
                            </div>
                        </div>

                        <div className="input-group">
                            <label className="input-label">Пароль</label>
                            <div style={{ position: 'relative' }}>
                                <Lock size={18} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                                <input
                                    type="password"
                                    className="input-field"
                                    style={{ paddingLeft: '40px' }}
                                    value="********"
                                    disabled={true}
                                />
                            </div>
                        </div>
                    </div>
                </form>
            </div>

            {/* 2FA Section */}
            <div className="card" style={{ marginBottom: '24px' }}>
                <h3 style={{ fontSize: '18px', fontWeight: 600, marginBottom: '16px' }}>Двухфакторная аутентификация</h3>
                <div style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    padding: '16px',
                    background: 'var(--background-color)',
                    borderRadius: 'var(--radius-md)',
                    border: '1px solid var(--border-color)'
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                        <div style={{
                            padding: '12px', background: is2FAEnabled ? 'rgba(34, 197, 94, 0.1)' : 'rgba(93, 124, 249, 0.1)',
                            borderRadius: '50%', color: is2FAEnabled ? 'var(--success-color)' : 'var(--primary-color)'
                        }}>
                            <Shield size={24} />
                        </div>
                        <div>
                            <div style={{ fontWeight: 600, marginBottom: '4px' }}>Microsoft Authenticator / TOTP</div>
                            <div style={{ fontSize: '14px', color: 'var(--text-secondary)' }}>
                                {is2FAEnabled ? 'Защита активна' : 'Используйте приложение для подтверждения входа'}
                            </div>
                        </div>
                    </div>

                    <label className="switch-container">
                        <input
                            type="checkbox"
                            checked={is2FAEnabled}
                            onChange={toggle2FA}
                            className="switch-input"
                        />
                        <span className="switch-slider">
                            <span className="switch-knob"></span>
                        </span>
                    </label>
                </div>
            </div>

            {/* Admin Permissions */}
            <div className="card" style={{ marginBottom: '24px' }}>
                <h3 style={{ fontSize: '18px', fontWeight: 600, marginBottom: '16px' }}>Права администраторов</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                    {[
                        { id: 'perm-users', label: 'Управление пользователями', desc: 'Просмотр, редактирование и блокировка пользователей' },
                        { id: 'perm-teams', label: 'Управление командами', desc: 'Создание и удаление команд, управление составом' },
                        { id: 'perm-tasks', label: 'Управление задачами', desc: 'Создание, редактирование и назначение задач' },
                        { id: 'perm-admin', label: 'Управление администраторами', desc: 'Одобрение заявок на администратора' },
                        { id: 'perm-delete', label: 'Право на удаление', desc: 'Возможность безвозвратного удаления записей', dangerous: true }
                    ].map((perm) => (
                        <div key={perm.id} style={{
                            display: 'flex',
                            justifyContent: 'space-between',
                            alignItems: 'center',
                            padding: '16px',
                            background: 'var(--background-color)',
                            borderRadius: 'var(--radius-md)',
                            border: '1px solid var(--border-color)'
                        }}>
                            <div>
                                <div style={{ fontWeight: 600, marginBottom: '4px', color: perm.dangerous ? 'var(--error-color)' : 'var(--text-primary)' }}>
                                    {perm.label}
                                </div>
                                <div style={{ fontSize: '14px', color: 'var(--text-secondary)' }}>
                                    {perm.desc}
                                </div>
                            </div>

                            <label className="switch-container">
                                <input
                                    type="checkbox"
                                    defaultChecked={!perm.dangerous}
                                    className="switch-input"
                                />
                                <span className="switch-slider">
                                    <span className="switch-knob"></span>
                                </span>
                            </label>
                        </div>
                    ))}
                </div>
            </div>

            {/* Danger Zone */}
            <div className="card" style={{ borderColor: 'var(--error-color)', borderWidth: '1px', borderStyle: 'solid' }}>
                <h3 style={{ fontSize: '18px', fontWeight: 600, marginBottom: '16px', color: 'var(--error-color)' }}>Опасная зона</h3>

                <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div>
                            <div style={{ fontWeight: 500 }}>Выйти из аккаунта</div>
                            <div style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>Завершить текущую сессию</div>
                        </div>
                        <button className="btn btn-outline" style={{ display: 'flex', alignItems: 'center', gap: '8px' }} onClick={() => supabase.auth.signOut()}>
                            <LogOut size={16} /> Выйти
                        </button>
                    </div>

                    <div style={{ height: '1px', background: 'var(--border-color)' }}></div>

                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div>
                            <div style={{ fontWeight: 500, color: 'var(--error-color)' }}>Удалить аккаунт</div>
                            <div style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>Это действие необратимо</div>
                        </div>
                        <button className="btn" style={{
                            background: 'var(--error-color)', color: 'white',
                            display: 'flex', alignItems: 'center', gap: '8px'
                        }}>
                            <AlertTriangle size={16} /> Удалить
                        </button>
                    </div>
                </div>
            </div>

            {/* MFA Enrollment Modal */}
            {showMfaModal && mfaData && (
                <div className="modal-overlay" onClick={() => setShowMfaModal(false)}>
                    <div className="modal-content" onClick={e => e.stopPropagation()} style={{ maxWidth: '400px', textAlign: 'center' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                            <h3 style={{ fontSize: '20px', fontWeight: 'bold' }}>Настройка 2FA</h3>
                            <button onClick={() => setShowMfaModal(false)}><X size={24} color="var(--text-secondary)" /></button>
                        </div>

                        <p style={{ color: 'var(--text-secondary)', marginBottom: '20px', fontSize: '14px' }}>
                            Отсканируйте этот QR-код в приложении Microsoft Authenticator или Google Authenticator
                        </p>

                        <div style={{
                            background: 'white', padding: '16px', borderRadius: '12px',
                            display: 'inline-block', marginBottom: '20px', boxShadow: 'var(--shadow-sm)'
                        }}>
                            <img
                                src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(mfaData.otpauth_url)}`}
                                alt="QR Code"
                                style={{ width: '200px', height: '200px' }}
                            />
                        </div>

                        <div style={{ marginBottom: '20px' }}>
                            <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '4px' }}>Код для ручного ввода:</p>
                            <code style={{ fontSize: '14px', background: 'var(--background-color)', padding: '4px 8px', borderRadius: '4px' }}>
                                {mfaData.secret}
                            </code>
                        </div>

                        <form onSubmit={handleVerifyEnrollment}>
                            <div className="input-group">
                                <label className="input-label" style={{ textAlign: 'left' }}>Введите 6-значный код</label>
                                <input
                                    type="text"
                                    className="input-field"
                                    placeholder="000 000"
                                    value={verifyCode}
                                    onChange={(e) => setVerifyCode(e.target.value.replace(/\D/g, ''))}
                                    maxLength={6}
                                    style={{ textAlign: 'center', fontSize: '18px', letterSpacing: '4px' }}
                                    required
                                />
                            </div>

                            {mfaError && (
                                <div style={{ color: 'var(--error-color)', fontSize: '14px', marginBottom: '16px' }}>
                                    {mfaError}
                                </div>
                            )}

                            <button type="submit" className="btn btn-primary" style={{ width: '100%' }} disabled={isEnrolling || verifyCode.length !== 6}>
                                {isEnrolling ? <Loader2 className="animate-spin" size={20} /> : 'Подтвердить и включить'}
                            </button>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;
