import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { supabase } from './lib/supabaseClient';
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import DashboardPage from './pages/DashboardPage';
import UsersPage from './pages/UsersPage';
import TeamsPage from './pages/TeamsPage';
import AdminPage from './pages/AdminPage';
import TasksPage from './pages/TasksPage';
import SubtasksPage from './pages/SubtasksPage';
import SettingsPage from './pages/SettingsPage';
import CalendarPage from './pages/CalendarPage';
import './index.css';

function App() {
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState(true);

  // Verify session from Supabase on load
  const verifySession = async () => {
    const userId = localStorage.getItem('admin_user_id');
    if (!userId) {
      setSession(null);
      setLoading(false);
      return;
    }

    try {
      // Fetch user from Supabase to verify they still exist and are admin
      const { data, error } = await supabase
        .from('users')
        .select('*')
        .eq('id', userId)
        .eq('role', 'admin')
        .single();

      if (error || !data) {
        // User doesn't exist or is no longer admin
        localStorage.removeItem('admin_user_id');
        setSession(null);
      } else {
        setSession(data);
      }
    } catch (err) {
      console.error('Session verify error:', err);
      localStorage.removeItem('admin_user_id');
      setSession(null);
    }

    setLoading(false);
  };

  useEffect(() => {
    verifySession();

    // Listen for session changes from Login
    const handleSessionChange = () => {
      verifySession();
    };

    window.addEventListener('session-changed', handleSessionChange);
    return () => window.removeEventListener('session-changed', handleSessionChange);
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('admin_user_id');
    setSession(null);
  };

  if (loading) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh', background: 'var(--background-color)', color: 'white' }}>
        Загрузка...
      </div>
    );
  }

  return (
    <Router>
      <Routes>
        <Route path="/login" element={!session ? <Login /> : <Navigate to="/dashboard" />} />
        <Route path="/register" element={!session ? <Register /> : <Navigate to="/dashboard" />} />

        <Route path="/dashboard" element={session ? <Dashboard onLogout={handleLogout} session={session} /> : <Navigate to="/login" />}>
          <Route index element={<Navigate to="overview" />} />
          <Route path="overview" element={<DashboardPage />} />
          <Route path="users" element={<UsersPage />} />
          <Route path="teams" element={<TeamsPage />} />
          <Route path="admin" element={<AdminPage />} />
          <Route path="tasks" element={<TasksPage />} />
          <Route path="subtasks" element={<SubtasksPage />} />
          <Route path="calendar" element={<CalendarPage />} />
          <Route path="settings" element={<SettingsPage />} />
        </Route>

        <Route path="/" element={<Navigate to="/login" />} />
      </Routes>
    </Router>
  );
}

export default App;
