import React, { useState, useEffect, useMemo } from 'react';
import { useOutletContext } from 'react-router-dom';
import { supabase } from '../lib/supabaseClient';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { CheckCircle2, Clock, AlertCircle, ListTodo, TrendingUp, Users, Copy, ChevronLeft, ChevronRight, Calendar as CalendarIcon, MoreHorizontal } from 'lucide-react';
import '../index.css';

const MONTHS_RU = ['Янв', 'Фев', 'Мар', 'Апр', 'Май', 'Июн', 'Июл', 'Авг', 'Сен', 'Окт', 'Ноя', 'Дек'];

const DashboardPage = () => {
    const { updateSearchCount } = useOutletContext();
    const [tasks, setTasks] = useState([]);
    const [users, setUsers] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        updateSearchCount(0);
    }, [updateSearchCount]);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setIsLoading(true);
        const [tasksRes, usersRes] = await Promise.all([
            // Fetch tasks with their assignees using explicit join syntax
            supabase.from('tasks').select('*, assignee:users!assignee_id(id, username)').order('created_at', { ascending: false }),
            supabase.from('users').select('*')
        ]);
        if (!tasksRes.error) {
            const mappedData = (tasksRes.data || []).map(t => ({
                ...t,
                assignee: t.users
            }));
            setTasks(mappedData);
        }
        if (!usersRes.error) setUsers(usersRes.data || []);
        setIsLoading(false);
    };

    const stats = useMemo(() => {
        const total = tasks.length;
        const done = tasks.filter(t => t.status === 'done').length;
        const inProgress = tasks.filter(t => t.status === 'in_progress').length;
        const todo = tasks.filter(t => t.status === 'todo').length;
        const overdue = tasks.filter(t => {
            if (!t.due_date || t.status === 'done') return false;
            return new Date(t.due_date) < new Date();
        }).length;
        return { total, done, inProgress, todo, overdue, users: users.length };
    }, [tasks, users]);

    const chartData = useMemo(() => {
        const now = new Date();
        const year = now.getFullYear();
        const data = MONTHS_RU.map((name, i) => ({
            name,
            completed: 0,
            incomplete: 0
        }));

        tasks.forEach(task => {
            const created = task.created_at ? new Date(task.created_at) : null;
            if (!created || created.getFullYear() !== year) return;
            const month = created.getMonth();
            if (task.status === 'done') {
                data[month].completed++;
            } else {
                data[month].incomplete++;
            }
        });

        return data;
    }, [tasks]);

    const copyToClipboard = (text) => {
        navigator.clipboard.writeText(text);
    };

    const getStatusLabel = (status) => {
        switch (status) {
            case 'done': return 'Выполнено';
            case 'in_progress': return 'В работе';
            case 'todo': return 'К выполнению';
            default: return status || '—';
        }
    };

    const getStatusClass = (status) => {
        switch (status) {
            case 'done': return 'status-success';
            case 'in_progress': return 'status-info';
            case 'todo': return 'status-warning';
            default: return 'status-neutral';
        }
    };



    if (isLoading) {
        return (
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '80px' }}>
                <div style={{ color: 'var(--text-secondary)', fontSize: '16px' }}>Загрузка данных...</div>
            </div>
        );
    }

    return (
        <div>
            {/* Stats Cards */}

            {/* Stats Cards */}
            <div className="dashboard-stats">
                <div className="dashboard-stat-card">
                    <div className="stat-icon" style={{ background: 'rgba(93, 124, 249, 0.1)' }}>
                        <ListTodo size={24} color="#5D7CF9" />
                    </div>
                    <div className="stat-number">{stats.total}</div>
                    <div className="stat-title">Всего задач</div>
                </div>
                <div className="dashboard-stat-card">
                    <div className="stat-icon" style={{ background: 'rgba(76, 175, 80, 0.1)' }}>
                        <CheckCircle2 size={24} color="#4CAF50" />
                    </div>
                    <div className="stat-number">{stats.done}</div>
                    <div className="stat-title">Выполнено</div>
                </div>
                <div className="dashboard-stat-card">
                    <div className="stat-icon" style={{ background: 'rgba(52, 152, 219, 0.1)' }}>
                        <Clock size={24} color="#3498db" />
                    </div>
                    <div className="stat-number">{stats.inProgress}</div>
                    <div className="stat-title">В работе</div>
                </div>
                <div className="dashboard-stat-card">
                    <div className="stat-icon" style={{ background: 'rgba(255, 107, 107, 0.1)' }}>
                        <AlertCircle size={24} color="#FF6B6B" />
                    </div>
                    <div className="stat-number">{stats.overdue}</div>
                    <div className="stat-title">Просрочено</div>
                </div>
                <div className="dashboard-stat-card">
                    <div className="stat-icon" style={{ background: 'rgba(155, 89, 182, 0.1)' }}>
                        <Users size={24} color="#9b59b6" />
                    </div>
                    <div className="stat-number">{stats.users}</div>
                    <div className="stat-title">Пользователей</div>
                </div>
            </div>

            {/* Chart */}
            <div className="chart-container">
                <div style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', marginBottom: '24px' }}>
                    <div className="chart-legend">
                        <div className="chart-legend-item">
                            <div className="chart-legend-dot" style={{ background: '#5D7CF9' }}></div>
                            Выполнено
                        </div>
                        <div className="chart-legend-item">
                            <div className="chart-legend-dot" style={{ background: '#FF6B6B' }}></div>
                            Не выполнено
                        </div>
                    </div>
                </div>
                <ResponsiveContainer width="100%" height={320}>
                    <BarChart data={chartData} barGap={4} barCategoryGap="20%">
                        <CartesianGrid strokeDasharray="3 3" stroke="var(--border-color)" vertical={false} />
                        <XAxis dataKey="name" stroke="var(--text-secondary)" fontSize={13} tickLine={false} axisLine={false} />
                        <YAxis stroke="var(--text-secondary)" fontSize={13} tickLine={false} axisLine={false} allowDecimals={false} />
                        <Tooltip
                            contentStyle={{
                                background: 'var(--surface-color)',
                                border: '1px solid var(--border-color)',
                                borderRadius: '12px',
                                boxShadow: 'var(--shadow-md)',
                                fontSize: '13px'
                            }}
                        />
                        <Bar dataKey="completed" name="Выполнено" fill="#5D7CF9" radius={[6, 6, 0, 0]} />
                        <Bar dataKey="incomplete" name="Не выполнено" fill="#FF6B6B" radius={[6, 6, 0, 0]} />
                    </BarChart>
                </ResponsiveContainer>
            </div>

            {/* Middle Stats Row */}
            <div className="stats-row">
                <div className="stat-card">
                    <div className="stat-label">Процент выполнения</div>
                    <div className="stat-value">
                        {stats.total > 0 ? Math.round((stats.done / stats.total) * 100) : 0}%
                        <span className="stat-change positive" style={{ fontSize: '14px' }}>
                            ↑ задач
                        </span>
                    </div>
                </div>
                <div className="stat-card">
                    <div className="stat-label">К выполнению</div>
                    <div className="stat-value">
                        {stats.todo}
                    </div>
                </div>
                <div className="stat-card">
                    <div className="stat-label">Активные пользователи</div>
                    <div className="stat-value">
                        {users.filter(u => u.status === 'active').length}
                    </div>
                </div>
            </div>



            {/* Task List */}
            <div className="card-static" style={{ overflow: 'hidden' }}>
                <div style={{ padding: '20px 24px', borderBottom: '1px solid var(--border-color)' }}>
                    <h3 style={{ fontSize: '16px', fontWeight: 700 }}>Список задач</h3>
                </div>
                <div className="table-container">
                    <table>
                        <thead>
                            <tr>
                                <th>ID</th>
                                <th>Название</th>
                                <th>Исполнитель</th>
                                <th>Приоритет</th>
                                <th>Дата</th>
                                <th>Статус</th>
                            </tr>
                        </thead>
                        <tbody>
                            {tasks.length === 0 ? (
                                <tr><td colSpan="6" style={{ textAlign: 'center', padding: '48px' }}>Нет задач</td></tr>
                            ) : tasks.slice(0, 10).map((task) => (
                                <tr key={task.id}>
                                    <td>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                                            <span style={{ color: 'var(--text-secondary)', fontSize: '13px' }}>#{task.id?.toString().slice(0, 8)}</span>
                                            <button className="copy-btn" onClick={() => copyToClipboard(task.id)} title="Копировать ID">
                                                <Copy size={14} />
                                            </button>
                                        </div>
                                    </td>
                                    <td style={{ fontWeight: 600 }}>{task.title}</td>
                                    <td>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                            <div style={{ width: '28px', height: '28px', borderRadius: '50%', background: 'var(--primary-light)', color: 'var(--primary-color)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px', fontWeight: 'bold' }}>
                                                {task.assignee?.username?.charAt(0) || '?'}
                                            </div>
                                            <div style={{ fontSize: '13px', color: 'var(--text-primary)', fontWeight: 500 }}>
                                                {task.assignee?.username || '—'}
                                            </div>
                                        </div>
                                    </td>
                                    <td>
                                        <span className={`status-badge ${task.priority === 'high' ? 'status-error' : task.priority === 'medium' ? 'status-warning' : 'status-success'}`}>
                                            {task.priority === 'high' ? 'Высокий' : task.priority === 'medium' ? 'Средний' : 'Низкий'}
                                        </span>
                                    </td>
                                    <td style={{ color: 'var(--text-secondary)' }}>
                                        {task.created_at ? new Date(task.created_at).toLocaleDateString() : '—'}
                                    </td>
                                    <td>
                                        <span className={`status-badge ${getStatusClass(task.status)}`}>
                                            {getStatusLabel(task.status)}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
                <div style={{ padding: '16px 24px', borderTop: '1px solid var(--border-color)', color: 'var(--text-secondary)', fontSize: '14px' }}>
                    Показано {Math.min(10, tasks.length)} из {tasks.length} задач
                </div>
            </div>
        </div>
    );
};

export default DashboardPage;
