import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { Mail, Lock, User, Loader2, CheckCircle } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';
import '../index.css';

const Register = () => {
    const [loading, setLoading] = useState(false);
    const [success, setSuccess] = useState(false);
    const [error, setError] = useState('');
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        password: ''
    });

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            // Check if email already exists in requests
            const { data: existing } = await supabase
                .from('admin_requests')
                .select('id')
                .eq('email', formData.email)
                .single();

            if (existing) {
                setError('Заявка с этим email уже существует');
                setLoading(false);
                return;
            }

            // Check if email already exists in users
            const { data: existingUser } = await supabase
                .from('users')
                .select('id')
                .eq('email', formData.email)
                .single();

            if (existingUser) {
                setError('Пользователь с этим email уже существует');
                setLoading(false);
                return;
            }

            // Save request to admin_requests table
            const { error: insertError } = await supabase
                .from('admin_requests')
                .insert([{
                    name: formData.name,
                    email: formData.email,
                    password: formData.password,
                    status: 'pending',
                    created_at: new Date().toISOString()
                }]);

            if (insertError) {
                setError('Ошибка отправки заявки: ' + insertError.message);
                setLoading(false);
                return;
            }

            setLoading(false);
            setSuccess(true);
            alert('Заявка успешно отправлена на рассмотрение!');
        } catch (err) {
            setError('Ошибка подключения к серверу');
            setLoading(false);
        }
    };

    if (success) {
        return (
            <div style={{
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                minHeight: '100vh',
                background: 'var(--background-color)'
            }}>
                <div className="card" style={{ width: '450px', maxWidth: '90%', textAlign: 'center' }}>
                    <div style={{ display: 'inline-flex', padding: '16px', borderRadius: '50%', background: 'rgba(76, 175, 80, 0.1)', marginBottom: '16px' }}>
                        <CheckCircle size={48} color="var(--success-color)" />
                    </div>
                    <h2 style={{ marginBottom: '12px' }}>Заявка принята</h2>
                    <p style={{ color: 'var(--text-secondary)', lineHeight: '1.6', marginBottom: '24px' }}>
                        Ваша заявка на регистрацию отправлена на рассмотрение. Мы свяжемся с вами в ближайшее время.
                        Как только администратор одобрит вашу заявку, вы сможете войти с указанным email <strong>{formData.email}</strong>.
                    </p>
                    <Link to="/login" className="btn btn-outline" style={{ width: '100%' }}>
                        Вернуться ко входу
                    </Link>
                </div>
            </div>
        );
    }

    return (
        <div style={{
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            minHeight: '100vh',
            background: 'var(--background-color)'
        }}>
            <div className="card" style={{ width: '400px', maxWidth: '90%' }}>
                <h2 style={{ textAlign: 'center', marginBottom: '8px', color: 'var(--text-primary)' }}>Подать заявку</h2>
                <p style={{ textAlign: 'center', fontSize: '13px', color: 'var(--text-secondary)', marginBottom: '24px' }}>
                    Заявка будет рассмотрена в течение 1-3 рабочих дней
                </p>

                {error && (
                    <div style={{
                        padding: '12px',
                        background: 'rgba(255, 107, 107, 0.1)',
                        color: 'var(--error-color)',
                        borderRadius: 'var(--radius-sm)',
                        marginBottom: '16px',
                        fontSize: '14px',
                        textAlign: 'center'
                    }}>
                        {error}
                    </div>
                )}

                <form onSubmit={handleSubmit}>
                    <div className="input-group">
                        <label className="input-label">Имя</label>
                        <div style={{ position: 'relative' }}>
                            <User size={18} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="text"
                                className="input-field"
                                style={{ paddingLeft: '40px' }}
                                placeholder="Иван Иванов"
                                required
                                value={formData.name}
                                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                            />
                        </div>
                    </div>

                    <div className="input-group">
                        <label className="input-label">Email</label>
                        <div style={{ position: 'relative' }}>
                            <Mail size={18} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="email"
                                className="input-field"
                                style={{ paddingLeft: '40px' }}
                                placeholder="email@example.com"
                                required
                                value={formData.email}
                                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                            />
                        </div>
                    </div>

                    <div className="input-group">
                        <label className="input-label">Пароль</label>
                        <div style={{ position: 'relative' }}>
                            <Lock size={18} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="password"
                                className="input-field"
                                style={{ paddingLeft: '40px' }}
                                placeholder="••••••••"
                                required
                                value={formData.password}
                                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                            />
                        </div>
                    </div>

                    <button
                        type="submit"
                        className="btn btn-primary"
                        style={{ width: '100%', marginTop: '8px' }}
                        disabled={loading}
                    >
                        {loading ? <Loader2 className="animate-spin" size={20} /> : 'Отправить заявку'}
                    </button>
                </form>

                <p style={{ marginTop: '16px', textAlign: 'center', fontSize: '12px', color: 'var(--text-secondary)', lineHeight: '1.5' }}>
                    Вашу заявку рассмотрят в течение 1-3 рабочих дней.
                    Создание аккаунта происходит только после одобрения администратором.
                </p>

                <div style={{ marginTop: '16px', textAlign: 'center', fontSize: '14px', color: 'var(--text-secondary)' }}>
                    Уже есть аккаунт? <Link to="/login" style={{ color: 'var(--primary-color)', textDecoration: 'none', fontWeight: 600 }}>Войти</Link>
                </div>
            </div>
        </div>
    );
};

export default Register;
