/* global BigInt */

/**
 * Robust TOTP verification using Web Crypto API (HMAC-SHA1)
 * Optimized for maximum reliability, cross-platform compatibility, and clock drift.
 */

// RFC 4648 Base32 Decoder
function base32ToBuffer(base32) {
    base32 = base32.replace(/=+$/, '').toUpperCase();
    const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    let bits = 0;
    let value = 0;
    let index = 0;
    const buffer = new Uint8Array((base32.length * 5) / 8 | 0);

    for (let i = 0; i < base32.length; i++) {
        const val = alphabet.indexOf(base32[i]);
        if (val === -1) continue;
        value = (value << 5) | val;
        bits += 5;
        if (bits >= 8) {
            buffer[index++] = (value >> (bits - 8)) & 255;
            bits -= 8;
        }
    }
    return buffer.buffer;
}

export async function verifyTOTP(secret, code) {
    if (!secret || !code) return false;
    const cleanCode = code.replace(/\D/g, '');
    if (cleanCode.length !== 6) return false;

    try {
        const secretBuffer = base32ToBuffer(secret);
        const time = Math.floor(Date.now() / 1000 / 30);

        // Window of ±3 steps (1.5 min total) to handle significant clock drift
        for (let i = -3; i <= 3; i++) {
            let stepLong = BigInt(time + i);
            const msg = new Uint8Array(8);
            for (let j = 7; j >= 0; j--) {
                msg[j] = Number(stepLong & 255n);
                stepLong >>= 8n;
            }

            const key = await crypto.subtle.importKey(
                'raw',
                secretBuffer,
                { name: 'HMAC', hash: 'SHA-1' },
                false,
                ['sign']
            );

            const hmacBuffer = await crypto.subtle.sign('HMAC', key, msg);
            const hmac = new Uint8Array(hmacBuffer);
            const offset = hmac[hmac.length - 1] & 0xf;
            const otpBinary = ((hmac[offset] & 0x7f) << 24) |
                ((hmac[offset + 1] & 0xff) << 16) |
                ((hmac[offset + 2] & 0xff) << 8) |
                (hmac[offset + 3] & 0xff);

            const otpCode = (otpBinary % 1000000).toString().padStart(6, '0');
            if (otpCode === cleanCode) return true;
        }
    } catch (err) {
        console.error('TOTP Critical Verification Error:', err);
    }
    return false;
}

/**
 * Generates a 16-character Base32 secret (80 bits).
 * Guaranteed compatible with Google and Microsoft Authenticator.
 */
export function generateTOTPSecret() {
    const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    let secret = '';
    const random = crypto.getRandomValues(new Uint8Array(10)); // 10 bytes = 80 bits

    let bits = 0;
    let val = 0;
    for (let i = 0; i < random.length; i++) {
        val = (val << 8) | random[i];
        bits += 8;
        while (bits >= 5) {
            secret += alphabet[(val >> (bits - 5)) & 31];
            bits -= 5;
        }
    }
    // Final padding to ensure exactly 16 chars
    while (secret.length < 16) secret += alphabet[Math.floor(Math.random() * 32)];
    return secret;
}
