import React, { useState, useEffect, useMemo } from 'react';
import { useOutletContext } from 'react-router-dom';
import { supabase } from '../lib/supabaseClient';
import { Users, MoreVertical, Filter, Trash2, Edit, X, Search } from 'lucide-react';
import '../index.css';

const TeamsPage = () => {
    const { searchTerm, updateSearchCount } = useOutletContext();
    const [teams, setTeams] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [actionMenuOpen, setActionMenuOpen] = useState(null);
    const [showCreateModal, setShowCreateModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const [selectedTeam, setSelectedTeam] = useState(null);
    const [teamSearch, setTeamSearch] = useState('');
    const [idSearch, setIdSearch] = useState('');
    const [dateFilter, setDateFilter] = useState('all');
    const [sortOrder, setSortOrder] = useState('az');
    const [editingTeamId, setEditingTeamId] = useState(null);

    useEffect(() => {
        fetchTeams();
    }, []);

    const fetchTeams = async () => {
        setIsLoading(true);
        // Basic fetch of teams. In a real app we'd join for member counts
        const { data, error } = await supabase
            .from('teams')
            .select('*')
            .order('created_at', { ascending: false });

        if (error) {
            console.error('Error fetching teams:', error);
        } else {
            setTeams(data || []);
        }
        setIsLoading(false);
    };

    const filteredTeams = useMemo(() => {
        let result = [...teams];

        if (searchTerm) {
            const lowerSearch = searchTerm.toLowerCase();
            result = result.filter(team => (team.name?.toLowerCase() || '').includes(lowerSearch));
        }

        if (teamSearch) {
            const lowerFilter = teamSearch.toLowerCase();
            result = result.filter(team => (team.name?.toLowerCase() || '').includes(lowerFilter));
        }

        if (idSearch) {
            result = result.filter(team => team.id?.toString().includes(idSearch));
        }

        if (dateFilter !== 'all') {
            const now = new Date();
            const start = dateFilter === 'today' ? new Date(now.setHours(0, 0, 0, 0)) : new Date(now.setDate(now.getDate() - 7));
            result = result.filter(team => new Date(team.created_at) >= start);
        }

        if (sortOrder === 'az') result.sort((a, b) => a.name.localeCompare(b.name));
        else result.sort((a, b) => b.name.localeCompare(a.name));

        return result;
    }, [teams, searchTerm, teamSearch, idSearch, dateFilter, sortOrder]);

    useEffect(() => {
        updateSearchCount(searchTerm ? filteredTeams.length : 0);
    }, [filteredTeams.length, searchTerm, updateSearchCount]);

    const handleDeleteTeam = async (id) => {
        if (window.confirm('Вы уверены, что хотите удалить эту команду?')) {
            const { error } = await supabase.from('teams').delete().eq('id', id);
            if (error) alert('Ошибка удаления: ' + error.message);
            else fetchTeams();
        }
    };

    const handleCreateTeam = async (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const name = formData.get('name');

        const { error } = await supabase.from('teams').insert([{ name }]);
        if (error) alert('Ошибка создания: ' + error.message);
        else {
            setShowCreateModal(false);
            fetchTeams();
        }
    };

    const handleUpdateActiveTeam = async (id, newName) => {
        if (!newName.trim()) return;
        const { error } = await supabase.from('teams').update({ name: newName }).eq('id', id);
        if (error) alert('Ошибка обновления: ' + error.message);
        else fetchTeams();
        setEditingTeamId(null);
    };

    const handleUpdateTeam = async (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const name = formData.get('name');

        const { error } = await supabase.from('teams').update({ name }).eq('id', selectedTeam.id);
        if (error) alert('Ошибка обновления: ' + error.message);
        else {
            setShowEditModal(false);
            fetchTeams();
        }
    };

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '24px' }}>
                <div style={{ display: 'flex', gap: '12px' }}>
                    <button className="btn btn-primary" onClick={() => setShowCreateModal(true)}>
                        + Создать команду
                    </button>
                </div>
            </div>

            <div className="card-static" style={{ marginBottom: '24px' }}>
                <div className="filter-bar">
                    <div className="filter-group" style={{ flex: 1 }}>
                        <label>Поиск по команде</label>
                        <div style={{ position: 'relative' }}>
                            <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="text"
                                className="filter-input"
                                placeholder="Поиск по команде..."
                                value={teamSearch}
                                onChange={(e) => setTeamSearch(e.target.value)}
                                style={{ paddingLeft: '36px', width: '100%' }}
                            />
                        </div>
                    </div>
                    <div className="filter-group" style={{ width: '180px' }}>
                        <label>Поиск по ID</label>
                        <div style={{ position: 'relative' }}>
                            <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
                            <input
                                type="text"
                                className="filter-input"
                                placeholder="ID..."
                                value={idSearch}
                                onChange={(e) => setIdSearch(e.target.value)}
                                style={{ paddingLeft: '36px', width: '100%' }}
                            />
                        </div>
                    </div>
                    <div className="filter-group">
                        <label>Дата</label>
                        <select className="filter-select" value={dateFilter} onChange={(e) => setDateFilter(e.target.value)}>
                            <option value="all">Все</option>
                            <option value="today">Сегодня</option>
                            <option value="week">Неделя</option>
                        </select>
                    </div>
                    <div className="filter-group">
                        <label>Сортировка</label>
                        <select className="filter-select" value={sortOrder} onChange={(e) => setSortOrder(e.target.value)}>
                            <option value="az">А-Я</option>
                            <option value="za">Я-А</option>
                        </select>
                    </div>
                </div>
            </div>

            <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
                <div className="table-container">
                    <table>
                        <thead>
                            <tr>
                                <th>Название</th>
                                <th>Идентификатор</th>
                                <th>Дата создания</th>
                                <th style={{ width: '60px' }}></th>
                            </tr>
                        </thead>
                        <tbody>
                            {isLoading ? (
                                <tr><td colSpan="4" style={{ textAlign: 'center', padding: '48px' }}>Загрузка...</td></tr>
                            ) : filteredTeams.length === 0 ? (
                                <tr><td colSpan="4" style={{ textAlign: 'center', padding: '48px' }}>Ничего не найдено</td></tr>
                            ) : filteredTeams.map((team) => (
                                <tr
                                    key={team.id}
                                    className={searchTerm && (team.name?.toLowerCase().includes(searchTerm.toLowerCase())) ? 'search-highlight' : ''}
                                >
                                    <td>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                            <div style={{
                                                width: '36px', height: '36px', borderRadius: '8px',
                                                background: 'var(--primary-light)', color: 'var(--primary-color)',
                                                display: 'flex', alignItems: 'center', justifyContent: 'center'
                                            }}>
                                                <Users size={18} />
                                            </div>
                                            {editingTeamId === team.id ? (
                                                <input
                                                    className="input-field"
                                                    autoFocus
                                                    defaultValue={team.name}
                                                    onBlur={(e) => handleUpdateActiveTeam(team.id, e.target.value)}
                                                    onKeyDown={(e) => {
                                                        if (e.key === 'Enter') handleUpdateActiveTeam(team.id, e.target.value);
                                                        if (e.key === 'Escape') setEditingTeamId(null);
                                                    }}
                                                    style={{ height: '36px', padding: '0 8px' }}
                                                />
                                            ) : (
                                                <div
                                                    style={{ fontWeight: 600, color: 'var(--text-primary)', cursor: 'pointer' }}
                                                    onClick={() => setEditingTeamId(team.id)}
                                                    title="Нажмите для редактирования"
                                                >
                                                    {team.name}
                                                </div>
                                            )}
                                        </div>
                                    </td>
                                    <td style={{ color: 'var(--text-secondary)', fontSize: '13px' }}>{team.id}</td>
                                    <td style={{ color: 'var(--text-secondary)' }}>
                                        {team.created_at ? new Date(team.created_at).toLocaleDateString() : '—'}
                                    </td>
                                    <td style={{ position: 'relative' }}>
                                        <button
                                            className="btn-icon"
                                            onClick={() => setActionMenuOpen(actionMenuOpen === team.id ? null : team.id)}
                                        >
                                            <MoreVertical size={18} />
                                        </button>

                                        {actionMenuOpen === team.id && (
                                            <div style={{
                                                position: 'absolute', right: '40px', top: '50%', transform: 'translateY(-50%)',
                                                background: 'var(--surface-color)', borderRadius: 'var(--radius-md)',
                                                boxShadow: 'var(--shadow-md)', border: '1px solid var(--border-color)',
                                                zIndex: 10, width: '160px', overflow: 'hidden'
                                            }}>
                                                <button
                                                    style={{ width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: 'var(--text-primary)' }}
                                                    onClick={() => {
                                                        setSelectedTeam(team);
                                                        setShowEditModal(true);
                                                        setActionMenuOpen(null);
                                                    }}
                                                >
                                                    <Edit size={14} /> Редактировать
                                                </button>
                                                <button
                                                    style={{ width: '100%', padding: '10px 16px', textAlign: 'left', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: 'var(--error-color)' }}
                                                    onClick={() => {
                                                        handleDeleteTeam(team.id);
                                                        setActionMenuOpen(null);
                                                    }}
                                                >
                                                    <Trash2 size={14} /> Удалить
                                                </button>
                                            </div>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                <div style={{
                    padding: '24px', borderTop: '1px solid var(--border-color)',
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center'
                }}>
                    <div style={{ color: 'var(--text-secondary)', fontSize: '14px' }}>
                        Показано: {filteredTeams.length} из {teams.length}
                    </div>
                </div>
            </div>

            {
                showCreateModal && (
                    <div className="modal-overlay" onClick={() => setShowCreateModal(false)}>
                        <div className="modal-content" onClick={e => e.stopPropagation()} style={{ maxWidth: '500px' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                                <h3 style={{ fontSize: '20px', fontWeight: 'bold' }}>Создать команду</h3>
                                <button onClick={() => setShowCreateModal(false)}><X size={24} color="var(--text-secondary)" /></button>
                            </div>
                            <form onSubmit={handleCreateTeam}>
                                <div className="input-group">
                                    <label className="input-label">Название команды</label>
                                    <input name="name" type="text" className="input-field" placeholder="Введите название" required />
                                </div>
                                <button type="submit" className="btn btn-primary" style={{ width: '100%', marginTop: '16px' }}>Создать</button>
                            </form>
                        </div>
                    </div>
                )
            }

            {
                showEditModal && selectedTeam && (
                    <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
                        <div className="modal-content" onClick={e => e.stopPropagation()} style={{ maxWidth: '500px' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                                <h3 style={{ fontSize: '20px', fontWeight: 'bold' }}>Редактировать команду</h3>
                                <button onClick={() => setShowEditModal(false)}><X size={24} color="var(--text-secondary)" /></button>
                            </div>
                            <form onSubmit={handleUpdateTeam}>
                                <div className="input-group">
                                    <label className="input-label">Название команды</label>
                                    <input name="name" type="text" className="input-field" defaultValue={selectedTeam.name} required />
                                </div>
                                <button type="submit" className="btn btn-primary" style={{ width: '100%', marginTop: '16px' }}>Сохранить</button>
                            </form>
                        </div>
                    </div>
                )
            }
        </div >
    );
};

export default TeamsPage;
